    ["src/core/runtime.lua"] = [[
local type = type
local tostring = tostring
local pcall = pcall
local tonumber = tonumber
local pairs = pairs
local os_clock = os.clock

local Runtime = {}
Runtime.__index = Runtime

function Runtime.new(options)
    options = options or {}

    local Scheduler = options.Scheduler
    local HealthMonitor = options.HealthMonitor
    local Dashboard = options.Dashboard

    local self = setmetatable({}, Runtime)
    self.Destroyed = false
    self.Started = false
    self.StartedAt = os_clock()
    self.ErrorCount = 0
    self.LastError = nil
    self.Health = "Healthy"
    self.Events = {}
    local schedulerOptions = {}
    local providedSchedulerOptions = options.SchedulerOptions
    if type(providedSchedulerOptions) == "table" then
        for key, value in pairs(providedSchedulerOptions) do schedulerOptions[key] = value end
    end
    local previousOnError = schedulerOptions.OnError
    schedulerOptions.OnError = function(state, message)
        self.ErrorCount = self.ErrorCount + 1
        self.LastError = message
        self:Emit("TaskError", state, message)
        if type(previousOnError) == "function" then pcall(previousOnError, state, message) end
    end
    self.Scheduler = type(Scheduler) == "table" and Scheduler.new(schedulerOptions) or nil
    self.HealthMonitor = type(HealthMonitor) == "table" and HealthMonitor.new(options.HealthOptions or {}) or nil
    self.Dashboard = type(Dashboard) == "table" and Dashboard.new(options.DashboardOptions or {}) or nil
    return self
end

function Runtime:On(name, callback)
    if self.Destroyed or type(name) ~= "string" or type(callback) ~= "function" then
        return function() end
    end

    local listeners = self.Events[name]
    if not listeners then
        listeners = {}
        self.Events[name] = listeners
    end

    local connection = {Connected = true, Callback = callback}
    listeners[connection] = true

    return function()
        if not connection.Connected then
            return
        end
        connection.Connected = false
        listeners[connection] = nil
    end
end

function Runtime:Emit(name, ...)
    if self.Destroyed then
        return
    end

    local listeners = self.Events[name]
    if not listeners then
        return
    end

    for connection in pairs(listeners) do
        if connection.Connected then
            pcall(connection.Callback, ...)
        end
    end
end

function Runtime:Register(name, callback, options)
    if self.Destroyed or not self.Scheduler then
        return nil
    end

    local state = self.Scheduler:Register(name, callback, options)
    if state then
        self:Emit("TaskRegistered", state)
    end
    return state
end

function Runtime:SetEnabled(name, enabled)
    if self.Destroyed or not self.Scheduler then
        return false
    end
    return self.Scheduler:SetEnabled(name, enabled)
end

function Runtime:IsEnabled(name)
    return self.Scheduler ~= nil and self.Scheduler:Get(name) ~= nil and self.Scheduler:Get(name).Enabled == true
end

function Runtime:GetTask(name)
    if not self.Scheduler then
        return nil
    end
    return self.Scheduler:Get(name)
end

function Runtime:Start()
    if self.Destroyed then
        return false
    end

    if self.Started then
        return true
    end

    self.Started = true
    self.StartedAt = os_clock()

    if self.Dashboard then
        self.Dashboard:Start()
    end

    if self.HealthMonitor then
        self.HealthMonitor:Start()
    end

    if self.Scheduler then
        self.Scheduler:Start()
    end

    self:Emit("Started")
    return true
end

function Runtime:GetSnapshot()
    local schedulerSnapshot = self.Scheduler and self.Scheduler:GetSnapshot() or {}
    local healthSnapshot = self.HealthMonitor and self.HealthMonitor:GetSnapshot() or {Status = "Unavailable"}
    local dashboardSnapshot = self.Dashboard and self.Dashboard:GetSnapshot() or {}

    self.Health = healthSnapshot.Status or "Unknown"

    return {
        Health = self.Health,
        Started = self.Started,
        StartedAt = self.StartedAt,
        Uptime = math.max(os_clock() - self.StartedAt, 0),
        ErrorCount = self.ErrorCount,
        LastError = self.LastError,
        Tasks = schedulerSnapshot,
        HealthMonitor = healthSnapshot,
        Dashboard = dashboardSnapshot
    }
end

function Runtime:Destroy()
    if self.Destroyed then
        return
    end

    self.Destroyed = true
    self.Started = false

    if self.Scheduler then
        pcall(self.Scheduler.Destroy, self.Scheduler)
    end

    if self.HealthMonitor then
        pcall(self.HealthMonitor.Destroy, self.HealthMonitor)
    end

    if self.Dashboard then
        pcall(self.Dashboard.Destroy, self.Dashboard)
    end

    self.Scheduler = nil
    self.HealthMonitor = nil
    self.Dashboard = nil
    self.Events = {}
    self.Health = "Destroyed"
end

return Runtime

]],
    ["src/core/scheduler.lua"] = [[
local task = task
local type = type
local tostring = tostring
local pcall = pcall
local os_clock = os.clock

local Scheduler = {}
Scheduler.__index = Scheduler

function Scheduler.new(options)
    options = options or {}

    local self = setmetatable({}, Scheduler)
    self.Tasks = {}
    self.Order = {}
    self.Destroyed = false
    self.Started = false
    self.NextId = 0
    self.DefaultInterval = tonumber(options.DefaultInterval) or 0.1
    self.MaxErrors = tonumber(options.MaxErrors) or 5
    self.OnError = type(options.OnError) == "function" and options.OnError or nil
    return self
end

-- Re-registering an existing name must not silently keep the stale callback:
-- backends re-register tasks after respawns with fresh upvalues. Swap the body in
-- place, bump the version (which retires the current thread) and restart if live.
function Scheduler:Register(name, callback, options)
    if self.Destroyed or type(name) ~= "string" or type(callback) ~= "function" then
        return nil
    end

    local existing = self.Tasks[name]
    if existing then
        existing.Callback = callback
        existing.Version = existing.Version + 1
        existing.Started = false
        if options then
            if options.Interval ~= nil then existing.Interval = math.max(tonumber(options.Interval) or existing.Interval, 0.01) end
            if options.Priority ~= nil then existing.Priority = tonumber(options.Priority) or existing.Priority end
            if options.Enabled ~= nil then existing.Enabled = options.Enabled ~= false end
        end
        if self.Started and existing.Enabled then
            self:StartTask(existing)
        end
        return existing
    end

    options = options or {}
    self.NextId = self.NextId + 1

    local state = {
        Id = self.NextId,
        Name = name,
        Callback = callback,
        Interval = math.max(tonumber(options.Interval) or self.DefaultInterval, 0.01),
        Priority = tonumber(options.Priority) or 0,
        Enabled = options.Enabled ~= false,
        Running = false,
        Errors = 0,
        LastError = nil,
        LastRun = 0,
        LastSuccess = 0,
        Started = false,
        RunningVersion = nil,
        Version = 0,
        Destroyed = false
    }

    self.Tasks[name] = state
    self.Order[#self.Order + 1] = state

    if self.Started and state.Enabled then
        self:StartTask(state)
    end

    return state
end

function Scheduler:SetEnabled(name, enabled)
    local state = self.Tasks[name]
    if not state or self.Destroyed then
        return false
    end

    state.Enabled = enabled == true
    state.Version = state.Version + 1
    state.RunningVersion = nil

    if state.Enabled and self.Started then
        self:StartTask(state)
    end

    return true
end

function Scheduler:Run(state)
    if self.Destroyed or state.Destroyed or not state.Enabled or state.Running then
        return false
    end

    state.Running = true
    state.LastRun = os_clock()

    local ok, err = pcall(state.Callback, state)
    state.Running = false

    if ok then
        state.Errors = 0
        state.LastError = nil
        state.LastSuccess = os_clock()
        return true
    end

    state.Errors = state.Errors + 1
    state.LastError = tostring(err)

    if state.Errors >= self.MaxErrors then
        state.Enabled = false
    end

    if self.OnError then
        pcall(self.OnError, state, state.LastError)
    end

    return false
end

-- A task can have at most one live thread per Version. The old guard
-- (`state.Started and state.Enabled`) skipped restarting when the previous thread
-- was still parked in task.wait, leaving an enabled task with no runner.
function Scheduler:StartTask(state)
    if self.Destroyed or state.Destroyed then
        return
    end

    if state.RunningVersion == state.Version and state.Started then
        return
    end

    state.Started = true
    local version = state.Version
    state.RunningVersion = version

    task.spawn(function()
        while not self.Destroyed and not state.Destroyed and state.Version == version do
            if state.Enabled then
                self:Run(state)
            end
            task.wait(state.Interval)
        end
        if state.RunningVersion == version then
            state.Started = false
            state.RunningVersion = nil
        end
    end)
end

function Scheduler:Start()
    if self.Destroyed then
        return false
    end

    if self.Started then
        return true
    end

    self.Started = true

    table.sort(self.Order, function(a, b)
        return a.Priority > b.Priority
    end)

    for _, state in ipairs(self.Order) do
        if state.Enabled then
            self:StartTask(state)
        end
    end

    return true
end

function Scheduler:Stop(name)
    local state = self.Tasks[name]
    if not state then
        return false
    end

    state.Enabled = false
    state.Version = state.Version + 1
    state.RunningVersion = nil
    return true
end

function Scheduler:Get(name)
    return self.Tasks[name]
end

function Scheduler:GetSnapshot()
    local result = {}

    for _, state in ipairs(self.Order) do
        result[#result + 1] = {
            Name = state.Name,
            Enabled = state.Enabled,
            Running = state.Running,
            Errors = state.Errors,
            LastError = state.LastError,
            LastRun = state.LastRun,
            LastSuccess = state.LastSuccess,
            Priority = state.Priority,
            Interval = state.Interval
        }
    end

    return result
end

function Scheduler:Destroy()
    if self.Destroyed then
        return
    end

    self.Destroyed = true

    for _, state in ipairs(self.Order) do
        state.Destroyed = true
        state.Enabled = false
        state.Version = state.Version + 1
        state.RunningVersion = nil
    end

    self.Tasks = {}
    self.Order = {}
end

return Scheduler

