    ["src/core/theme.lua"] = [[
-- DepHub UI theme.
--
-- Design tokens ported from the authored interface mockup (dephub.css). Every
-- colour and metric here is a direct translation of a CSS custom property or a
-- hard-coded surface value, so the in-game panel reads the same as the preview.
--
-- Colours are expressed as {r, g, b} in 0..255. Helpers convert them to the
-- Roblox types the panel needs. Keep this file free of engine side effects so it
-- can also be read by tests.

local Theme = {}

local function rgb(r, g, b)
    return {r = r, g = g, b = b}
end

-- :root tokens
Theme.Accent = rgb(188, 188, 188)        -- --accent: #bcbcbc
Theme.Bg = rgb(9, 9, 9)                  -- --bg: #090909
Theme.Surface = rgb(16, 16, 16)          -- --surface: #101010
Theme.Line = rgb(37, 37, 37)             -- --line: #252525
Theme.Text = rgb(222, 222, 222)          -- --text: #dedede
Theme.Muted = rgb(154, 154, 154)         -- --muted: #9a9a9a
Theme.Quiet = rgb(119, 119, 119)         -- --quiet: #777

-- Panel geometry (--width/--height with the same clamps as the mockup)
Theme.PanelWidth = 840
Theme.PanelHeight = 560
Theme.PanelRadius = 12
Theme.PanelBorder = rgb(44, 44, 44)      -- border: 1px solid #2c2c2c
Theme.HeaderHeight = 100                 -- --header: 100px
Theme.FooterHeight = 40                  -- --footer: 40px
Theme.SidebarWidth = 160                 -- grid-template-columns: 160px ...

-- Header / brand
Theme.BrandAccent = rgb(209, 209, 209)   -- .header-mark background #d1d1d1
Theme.BrandInk = rgb(23, 23, 23)         -- .header-mark color #171717
Theme.LeftPad = 24                       -- --left: 24px
Theme.BrandTop = 20                      -- --brand-top: 20px

-- Window buttons (macOS traffic lights)
Theme.CloseButton = rgb(255, 96, 88)     -- #ff6058
Theme.MinButton = rgb(254, 188, 46)      -- #febc2e
Theme.MaxButton = rgb(40, 200, 64)       -- #28c840

-- Navigation
Theme.NavBorder = rgb(28, 28, 28)        -- border-right: 1px solid #1c1c1c
Theme.NavIdle = rgb(146, 146, 146)       -- nav button color #929292
Theme.NavActiveBg = rgb(26, 26, 26)      -- nav button.active background #1a1a1a
Theme.NavActiveText = rgb(227, 227, 227) -- nav button.active color #e3e3e3
Theme.NavHoverBg = rgb(22, 22, 22)       -- nav button:hover #161616

-- Main content
Theme.MainBg = rgb(12, 12, 12)           -- main background #0c0c0c
Theme.RowBg = rgb(17, 17, 17)            -- .row background #111
Theme.RowHoverBg = rgb(22, 22, 22)       -- .row:hover #161616
Theme.SectionLabel = rgb(153, 153, 153)  -- .section-label #999
Theme.Heading = rgb(222, 222, 222)       -- h1 inherits --text
Theme.HelpText = rgb(146, 146, 146)      -- .help #929292

-- Controls
Theme.FieldBg = rgb(17, 17, 17)          -- .field background #111
Theme.FieldBorder = rgb(51, 51, 51)      -- .field border #333
Theme.FieldFocusBg = rgb(22, 22, 22)     -- .field:focus #161616
Theme.ToggleOff = rgb(48, 48, 48)        -- .toggle background #303030
Theme.ToggleOffBorder = rgb(68, 68, 68)  -- .toggle border #444
Theme.ToggleKnobOff = rgb(148, 148, 148) -- .toggle::after background #949494
Theme.ToggleKnobOn = rgb(34, 34, 34)     -- .toggle:checked::after #222
Theme.ActionBg = rgb(29, 29, 29)         -- .action background #1d1d1d
Theme.ActionBorder = rgb(58, 58, 58)     -- .action border #3a3a3a
Theme.ActionHoverBg = rgb(39, 39, 39)    -- .action:hover #272727
Theme.ActionHoverBorder = rgb(90, 90, 90)-- .action:hover border #5a5a5a
Theme.PrimaryBg = rgb(204, 204, 204)     -- .primary background #ccc
Theme.PrimaryInk = rgb(22, 22, 22)       -- .primary color #161616

-- Footer
Theme.FooterBorder = rgb(34, 34, 34)     -- border-top: 1px solid #222
Theme.FooterText = rgb(139, 139, 139)    -- footer color #8b8b8b

-- Feedback
Theme.ToastBg = rgb(21, 21, 21)          -- .toast background #151515
Theme.ToastBorder = rgb(58, 58, 58)      -- .toast border #3a3a3a
Theme.ToastError = rgb(121, 80, 80)      -- .toast.error border #795050
Theme.ModalBg = rgb(18, 18, 18)          -- dialog background #121212
Theme.ModalBorder = rgb(66, 66, 66)      -- dialog border #424242
Theme.NoticeBg = rgb(17, 17, 17)         -- .notice background #111

-- Motion (ms). The mockup reduces these under prefers-reduced-motion; the panel
-- exposes Theme.Reduced so callers can honour the same intent.
Theme.Reduced = false
Theme.Duration = {
    Fast = 0.18,
    Window = 0.30,
    Enter = 0.23,
    Tab = 0.22,
    Toast = 0.30,
    Modal = 0.25,
}

-- Convert a {r,g,b} token to Color3. Kept local-free so it works whether or not
-- Color3 is present at load time.
function Theme.Color(token)
    if token == nil then return Color3.fromRGB(255, 255, 255) end
    return Color3.fromRGB(token.r, token.g, token.b)
end

-- Blend toward black by factor (0 keeps colour, 1 gives black).
function Theme.Darken(token, factor)
    local f = 1 - math.clamp(factor or 0, 0, 1)
    return Color3.fromRGB(
        math.floor(token.r * f),
        math.floor(token.g * f),
        math.floor(token.b * f)
    )
end

-- UDim2 helpers used repeatedly by the panel layout.
function Theme.px(n)
    return UDim2.fromOffset(n, n)
end

return Theme

]],
    ["src/core/tween-movement.lua"] = [[
local Players=game:GetService("Players")
local TweenService=game:GetService("TweenService")
local RunService=game:GetService("RunService")
local Workspace=game:GetService("Workspace")

local Movement={}
Movement.__index=Movement

function Movement.new(config)
    config=config or {}

    return setmetatable({
        Player=Players.LocalPlayer,
        Speed=tonumber(config.Speed) or 220,
        NearSpeed=tonumber(config.NearSpeed) or 440,
        NearDistance=math.max(tonumber(config.NearDistance) or 380,0),
        DirectDistance=math.max(tonumber(config.DirectDistance) or 12,0),
        ArrivalRadius=math.max(tonumber(config.ArrivalRadius) or 0.75,0.01),
        MinDuration=tonumber(config.MinDuration) or 0.03,
        MaxSegmentDuration=tonumber(config.MaxSegmentDuration) or 3,
        SegmentPause=tonumber(config.SegmentPause) or 0.5,
        Priorities=type(config.Priorities)=="table" and config.Priorities or {},
        UsePhysics=config.UsePhysics~=false,
        Tween=nil,
        SteppedConnection=nil,
        HeartbeatConnection=nil,
        ActiveHumanoid=nil,
        ActiveRoot=nil,
        CollisionState={},
        ControlState=nil,
        LastClearCFrame=nil,
        Moving=false,
        MoveToken=0,
        ActiveOwner=nil,
        ActivePriority=-math.huge,
        Destroyed=false
    },Movement)
end

function Movement:_character()
    local character=self.Player and self.Player.Character
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    local root=character and character:FindFirstChild("HumanoidRootPart")

    if not humanoid or humanoid.Health<=0 or not root then
        return nil
    end

    return humanoid,root
end

function Movement:_toCFrame(target)
    local kind=typeof(target)

    if kind=="CFrame" then
        return target
    elseif kind=="Vector3" then
        return CFrame.new(target)
    elseif kind=="Instance" and target:IsA("BasePart") then
        return target.CFrame
    end

    return nil
end

function Movement:_isRootClear(cframe,character)
    local params=OverlapParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances={character}

    local ok,parts=pcall(
        Workspace.GetPartBoundsInBox,
        Workspace,
        cframe,
        Vector3.new(1.8,2,1.8),
        params
    )

    if not ok then
        return true
    end

    for _,part in ipairs(parts) do
        if part:IsA("BasePart") and part.CanCollide then
            return false
        end
    end

    return true
end

function Movement:_noclip(character)
    for _,part in ipairs(character:GetDescendants()) do
        if part:IsA("BasePart") then
            if self.CollisionState[part]==nil then
                self.CollisionState[part]=part.CanCollide
            end
            part.CanCollide=false
        end
    end
end

function Movement:_applyTravelState(humanoid,root)
    self.CollisionState={}
    self.ControlState={
        WalkSpeed=humanoid.WalkSpeed,
        JumpPower=humanoid.JumpPower,
        JumpHeight=humanoid.JumpHeight,
        AutoRotate=humanoid.AutoRotate
    }

    humanoid.WalkSpeed=0
    humanoid.JumpPower=0
    humanoid.JumpHeight=0
    humanoid.AutoRotate=false
    self:_noclip(root.Parent)
end

function Movement:_restoreTravelState(humanoid)
    for part,canCollide in pairs(self.CollisionState) do
        if part and part.Parent then
            part.CanCollide=canCollide
        end
    end
    table.clear(self.CollisionState)

    local state=self.ControlState
    self.ControlState=nil

    if humanoid and humanoid.Parent and state then
        humanoid.WalkSpeed=state.WalkSpeed
        humanoid.JumpPower=state.JumpPower
        humanoid.JumpHeight=state.JumpHeight
        humanoid.AutoRotate=state.AutoRotate
    end

    if humanoid and humanoid.Parent and humanoid.Health>0 and self.UsePhysics and humanoid:GetState()==Enum.HumanoidStateType.Physics then
        pcall(humanoid.ChangeState,humanoid,Enum.HumanoidStateType.GettingUp)
    end
end

function Movement:_resolveSpeed(remaining,requested)
    local explicit=tonumber(requested)

    if explicit and explicit>0 then
        return explicit
    end

    if self.NearSpeed and self.NearSpeed>0 and self.NearDistance>0 and remaining<=self.NearDistance then
        return self.NearSpeed
    end

    return self.Speed
end

function Movement:GetProfile()
    return {
        Speed=self.Speed,
        NearSpeed=self.NearSpeed,
        NearDistance=self.NearDistance,
        DirectDistance=self.DirectDistance,
        ArrivalRadius=self.ArrivalRadius,
        MinDuration=self.MinDuration,
        MaxSegmentDuration=self.MaxSegmentDuration,
        SegmentPause=self.SegmentPause
    }
end

function Movement:GetOwner()
    return self.ActiveOwner,self.ActivePriority
end

function Movement:IsOwnedBy(owner)
    return self.ActiveOwner~=nil and self.ActiveOwner==tostring(owner)
end

function Movement:Stop(preservePosition,owner)
    if owner~=nil and self.ActiveOwner~=nil and self.ActiveOwner~=tostring(owner) then
        return false,"owner mismatch"
    end

    self.MoveToken+=1

    local tween=self.Tween
    local stepped=self.SteppedConnection
    local heartbeat=self.HeartbeatConnection
    local humanoid=self.ActiveHumanoid
    local root=self.ActiveRoot
    local lastClear=self.LastClearCFrame

    self.Tween=nil
    self.SteppedConnection=nil
    self.HeartbeatConnection=nil
    self.ActiveHumanoid=nil
    self.ActiveRoot=nil
    self.LastClearCFrame=nil
    self.Moving=false
    self.ActiveOwner=nil
    self.ActivePriority=-math.huge

    if tween then pcall(tween.Cancel,tween) end
    if stepped then pcall(stepped.Disconnect,stepped) end
    if heartbeat then pcall(heartbeat.Disconnect,heartbeat) end

    if root and root.Parent then
        if not preservePosition and not self:_isRootClear(root.CFrame,root.Parent) and lastClear then
            root.CFrame=lastClear
        end

        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero
    end

    self:_restoreTravelState(humanoid)
    return true
end

function Movement:CancelOwner(owner,preservePosition)
    if not self:IsOwnedBy(owner) then
        return false
    end

    return self:Stop(preservePosition~=false,owner)
end

function Movement:IsMoving()
    return self.Moving==true
end

function Movement:FlyTo(target,speed,owner,priority)
    if self.Destroyed then
        return false,"destroyed"
    end

    local goal=self:_toCFrame(target)
    if not goal then
        return false,"invalid target"
    end

    local humanoid,root=self:_character()
    if not humanoid or not root then
        return false,"character unavailable"
    end

    local requestedSpeed=tonumber(speed)
    if requestedSpeed and requestedSpeed<=0 then
        return false,"invalid speed"
    end

    if self.Speed<=0 then
        return false,"invalid speed"
    end

    local moveOwner=tostring(owner or "default")
    local configuredPriority=tonumber(self.Priorities[moveOwner]) or 0
    local movePriority=tonumber(priority) or configuredPriority

    if self.Moving and self.ActiveOwner and self.ActiveOwner~=moveOwner and movePriority<self.ActivePriority then
        return false,"busy",self.ActiveOwner
    end

    self:Stop(true)
    local token=self.MoveToken
    local distance=(root.Position-goal.Position).Magnitude

    if distance<=self.ArrivalRadius then
        root.CFrame=goal
        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero
        return true
    end

    if self.DirectDistance>0 and distance<=self.DirectDistance then
        root.CFrame=goal
        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero
        return true
    end

    self.Moving=true
    self.ActiveOwner=moveOwner
    self.ActivePriority=movePriority
    self.ActiveHumanoid=humanoid
    self.ActiveRoot=root
    self:_applyTravelState(humanoid,root)

    if self:_isRootClear(root.CFrame,root.Parent) then
        self.LastClearCFrame=root.CFrame
    end

    root.AssemblyLinearVelocity=Vector3.zero
    root.AssemblyAngularVelocity=Vector3.zero

    if self.UsePhysics then
        pcall(humanoid.ChangeState,humanoid,Enum.HumanoidStateType.Physics)
    end

    self.SteppedConnection=RunService.Stepped:Connect(function()
        if token~=self.MoveToken or not root.Parent then return end

        self:_noclip(root.Parent)
        humanoid.WalkSpeed=0
        humanoid.JumpPower=0
        humanoid.JumpHeight=0
        humanoid.AutoRotate=false
    end)

    local lastClearCheck=0

    self.HeartbeatConnection=RunService.Heartbeat:Connect(function()
        if token~=self.MoveToken then return end

        if not root.Parent or humanoid.Health<=0 then
            self:Stop(true,moveOwner)
            return
        end

        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero

        local now=os.clock()
        if now-lastClearCheck>=0.15 then
            lastClearCheck=now

            if self:_isRootClear(root.CFrame,root.Parent) then
                self.LastClearCFrame=root.CFrame
            end
        end
    end)

    local completed=true

    while token==self.MoveToken do
        local delta=goal.Position-root.Position
        local remaining=delta.Magnitude

        if remaining<=self.ArrivalRadius then
            root.CFrame=goal
            break
        end

        local moveSpeed=self:_resolveSpeed(remaining,requestedSpeed)
        local segmentDuration=math.min(remaining/moveSpeed,self.MaxSegmentDuration)
        local segmentDistance=math.min(remaining,moveSpeed*self.MaxSegmentDuration)
        local nextPosition=root.Position+delta.Unit*segmentDistance
        local segmentGoal=CFrame.new(nextPosition)*goal.Rotation

        local ok,tween=pcall(function()
            return TweenService:Create(
                root,
                TweenInfo.new(math.max(segmentDuration,self.MinDuration),Enum.EasingStyle.Linear),
                {CFrame=segmentGoal}
            )
        end)

        if not ok then
            self:Stop(true,moveOwner)
            return false,tostring(tween)
        end

        self.Tween=tween
        tween:Play()

        local playbackState=tween.Completed:Wait()

        if token~=self.MoveToken then
            return false,"cancelled"
        end

        if playbackState~=Enum.PlaybackState.Completed then
            completed=false
            break
        end

        self.Tween=nil
        root.AssemblyLinearVelocity=Vector3.zero
        root.AssemblyAngularVelocity=Vector3.zero

        if remaining>segmentDistance+0.05 and self.SegmentPause>0 then
            local holdCFrame=root.CFrame
            local pauseUntil=os.clock()+self.SegmentPause

            while token==self.MoveToken and os.clock()<pauseUntil do
                if not root.Parent or humanoid.Health<=0 then
                    break
                end

                root.CFrame=holdCFrame
                root.AssemblyLinearVelocity=Vector3.zero
                root.AssemblyAngularVelocity=Vector3.zero
                RunService.Heartbeat:Wait()
            end
        end
    end

    if token~=self.MoveToken then
        return false,"cancelled"
    end

    self:Stop(true,moveOwner)
    return completed
end

function Movement:SetSpeed(value)
    value=tonumber(value)
    if not value or value<=0 then
        return false
    end

    self.Speed=value
    return true
end

function Movement:SetNearSpeed(value,distance)
    value=tonumber(value)
    distance=tonumber(distance)

    if not value or value<=0 or not distance or distance<=0 then
        return false
    end

    self.NearSpeed=value
    self.NearDistance=distance
    return true
end

function Movement:Destroy()
    if self.Destroyed then return end
    self:Stop()
    self.Destroyed=true
end

return Movement

]],
    ["src/core/ui-guard.lua"] = [[
local game=game
local type=type
local pcall=pcall
local ipairs=ipairs

local Factory={}

function Factory.new()
    local Players=game:GetService("Players")
    local RunService=game:GetService("RunService")
    local LocalPlayer=Players.LocalPlayer or Players.PlayerAdded:Wait()
    local PlayerGui=LocalPlayer:FindFirstChildOfClass("PlayerGui") or LocalPlayer:WaitForChild("PlayerGui",15)

    local self={
        Destroyed=false,
        Started=false,
        Connections={},
        Tracked=setmetatable({},{__mode="k"}),
        Accumulator=0,
        PlayerGui=PlayerGui,
        Target=nil
    }

    local function disconnectAll(list)
        for i=#list,1,-1 do
            local connection=list[i]
            list[i]=nil
            if connection then pcall(connection.Disconnect,connection) end
        end
    end

    function self:_resolveTarget()
        if type(gethui)=="function" then
            local ok,result=pcall(gethui)
            if ok and typeof(result)=="Instance" then
                return result
            end
        end
        return self.PlayerGui
    end

    function self:_isDepHub(gui)
        return gui
            and gui:IsA("ScreenGui")
            and string.find(string.lower(gui.Name),"dephub",1,true)~=nil
    end

    function self:_enforce(gui)
        if self.Destroyed or not self:_isDepHub(gui) or not gui.Parent then return end

        pcall(function()
            gui.Enabled=true
        end)

        pcall(function()
            gui.ResetOnSpawn=false
        end)

        pcall(function()
            gui.DisplayOrder=2147483647
        end)

        pcall(function()
            gui.ZIndexBehavior=Enum.ZIndexBehavior.Global
        end)

        pcall(function()
            gui.OnTopOfCoreBlur=true
        end)

        local target=self.Target or self:_resolveTarget()
        self.Target=target

        if target and target~=self.PlayerGui and gui.Parent~=target then
            pcall(function()
                gui.Parent=target
            end)
        end
    end

    function self:_track(gui)
        if not self:_isDepHub(gui) then return end

        self:_enforce(gui)

        if self.Tracked[gui] then return end
        self.Tracked[gui]=true

        self.Connections[#self.Connections+1]=gui:GetPropertyChangedSignal("Enabled"):Connect(function()
            if not self.Destroyed and gui.Parent and not gui.Enabled then
                self:_enforce(gui)
            end
        end)

        self.Connections[#self.Connections+1]=gui:GetPropertyChangedSignal("DisplayOrder"):Connect(function()
            if not self.Destroyed and gui.Parent and gui.DisplayOrder~=2147483647 then
                self:_enforce(gui)
            end
        end)
    end

    function self:_scan()
        if self.PlayerGui then
            for _,child in ipairs(self.PlayerGui:GetChildren()) do
                self:_track(child)
            end
        end

        local target=self.Target or self:_resolveTarget()
        self.Target=target

        if target and target~=self.PlayerGui then
            for _,child in ipairs(target:GetChildren()) do
                self:_track(child)
            end
        end

        for gui in pairs(self.Tracked) do
            if gui and gui.Parent then
                self:_enforce(gui)
            end
        end
    end

    function self:Start()
        if self.Destroyed or self.Started then return false end

        self.Started=true
        self.Target=self:_resolveTarget()
        self:_scan()

        if self.PlayerGui then
            self.Connections[#self.Connections+1]=self.PlayerGui.ChildAdded:Connect(function(child)
                task.defer(function()
                    if not self.Destroyed then self:_track(child) end
                end)
            end)
        end

        if self.Target and self.Target~=self.PlayerGui then
            self.Connections[#self.Connections+1]=self.Target.ChildAdded:Connect(function(child)
                task.defer(function()
                    if not self.Destroyed then self:_track(child) end
                end)
            end)
        end

        self.Connections[#self.Connections+1]=RunService.Heartbeat:Connect(function(dt)
            if self.Destroyed then return end
            self.Accumulator=self.Accumulator+dt
            if self.Accumulator<0.5 then return end
            self.Accumulator=0
            self:_scan()
        end)

        return true
    end

    function self:Destroy()
        if self.Destroyed then return end

        self.Destroyed=true
        self.Started=false
        disconnectAll(self.Connections)
        self.Tracked=setmetatable({},{__mode="k"})
    end

    return self
end

return Factory

]],
    ["src/core/updater.lua"] = [[
local game = game
local task = task
local type = type
local tostring = tostring
local tonumber = tonumber
local pcall = pcall
local math_random = math.random
local os_clock = os.clock

local GetService = game.GetService
local Players = GetService(game, "Players")
local HttpService = GetService(game, "HttpService")
local TeleportService = GetService(game, "TeleportService")

local LocalPlayer = Players.LocalPlayer

local sourceBase = ((type(getgenv)=="function" and getgenv() or _G).__DEPHUB or {}).SourceBaseURL or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"
local MANIFEST_URL = sourceBase .. "src/update-manifest.json"
local SERVERS_URL = "https://games.roblox.com/v1/games/%s/servers/Public?sortOrder=Asc&limit=100"
local COMPARE_URL = "https://api.github.com/repos/glowpkj/DepHub/compare/%s...%s"

local Updater = {}
Updater.__index = Updater

local function silent()
end

local updateLog = silent
local updateWarn = silent

local function httpGet(url)
    local ok, result = pcall(function()
        return __dephubHttpGet(url)
    end)
    if ok and type(result) == "string" and #result > 0 then
        return true, result
    end
    return false, ok and "Resposta vazia" or tostring(result)
end

local function decode(source)
    local ok, result = pcall(function()
        return HttpService:JSONDecode(source)
    end)
    if ok and type(result) == "table" then
        return true, result
    end
    return false, ok and "JSON invalido" or tostring(result)
end

local function buildSet(list)
    local result = {}
    if type(list) ~= "table" then
        return result
    end
    for _, value in ipairs(list) do
        if type(value) == "string" then
            result[value] = true
        end
    end
    return result
end

function Updater.new(options)
    options = options or {}
    local self = setmetatable({}, Updater)
    self.PlaceId = tostring(options.PlaceId or game.PlaceId)
    self.GameId = tostring(options.GameId or game.GameId)
    self.ManifestId = tostring(options.ManifestId or self.GameId)
    self.CurrentVersion = options.CurrentVersion and tostring(options.CurrentVersion) or nil
    self.CurrentCommit = options.CurrentCommit and tostring(options.CurrentCommit) or nil
    self.PollInterval = tonumber(options.PollInterval) or 15
    self.Mode = options.Mode or "serverhop"
    self.StartupGrace = tonumber(options.StartupGrace) or 90
    self.StartedAt = os_clock()
    self.CancelledVersions = {}
    self.RejectedVersions = {}
    self.Destroyed = false
    self.Started = false
    self.PendingUpdate = nil
    self.ActionInProgress = false
    return self
end

function Updater:FetchVersion()
    local ok, source = httpGet(MANIFEST_URL .. "?dephubupdate=" .. tostring(math_random(1000000, 9999999)))
    if not ok then
        return false, source
    end

    if self.Destroyed then return false, "Updater destruido" end
    local decoded, manifest = decode(source)
    if not decoded then
        return false, manifest
    end

    local games = manifest.games
    local info = type(games) == "table" and (games[self.ManifestId] or games[self.PlaceId]) or nil
    if type(info) ~= "table" or not info.version then
        return false, "Jogo sem versao registrada"
    end

    local commit = tostring(info.commit or manifest.commit or "")
    local files = type(info.files) == "table" and info.files or {}

    return true, {
        Version = tostring(info.version),
        Name = tostring(info.name or "DepHub"),
        Commit = commit,
        Files = files
    }
end

function Updater:ValidateBackendChange(info)
    if not self.CurrentCommit or self.CurrentCommit == "" then
        return false
    end

    if not info.Commit or info.Commit == "" then
        return false
    end

    if self.CurrentCommit == info.Commit then
        return false
    end

    local url = string.format(COMPARE_URL, self.CurrentCommit, info.Commit)
    local ok, source = httpGet(url)
    if not ok then
        return false
    end

    local decoded, compareData = decode(source)
    if not decoded then
        return false
    end

    local trackedFiles = buildSet(info.Files)
    local changedTracked = {}

    if type(compareData.files) == "table" then
        for _, file in ipairs(compareData.files) do
            local filename = type(file) == "table" and file.filename or nil
            if filename and trackedFiles[filename] then
                changedTracked[#changedTracked + 1] = filename
            end
        end
    end

    return #changedTracked > 0
end

-- Without a frontend, detected updates wait for explicit action.
function Updater:Cancel()
    if self.ActionInProgress then return end
    if self.PendingUpdate then
        self.CancelledVersions[self.PendingUpdate.Version] = true
        self.PendingUpdate = nil
    end
end

function Updater:ApplyPending()
    if self.Destroyed or self.ActionInProgress or not self.PendingUpdate then return false end
    return self:Teleport()
end

function Updater:GetServer()
    local url = string.format(SERVERS_URL, self.PlaceId)
    local ok, source = httpGet(url)
    if not ok then
        return false, source
    end

    local decoded, data = decode(source)
    if not decoded then
        return false, data
    end

    local candidates = {}
    if type(data.data) == "table" then
        for _, server in data.data do
            if type(server) == "table" and server.id and tonumber(server.playing) and tonumber(server.maxPlayers) then
                if server.id ~= game.JobId and server.playing < server.maxPlayers then
                    candidates[#candidates + 1] = server.id
                end
            end
        end
    end

    if #candidates == 0 then
        return false, "Nenhum servidor disponivel"
    end

    return true, candidates[math_random(1, #candidates)]
end

function Updater:Teleport()
    if self.Destroyed or self.ActionInProgress then
        return false
    end

    self.ActionInProgress = true
    self.PendingUpdate = nil

    if self.Mode == "rejoin" then
        local ok = pcall(function()
            TeleportService:Teleport(tonumber(self.PlaceId), LocalPlayer)
        end)
        if not ok then self.ActionInProgress = false end
        return ok
    end

    local ok, jobId = self:GetServer()
    if ok and jobId then
        local teleported = pcall(function()
            TeleportService:TeleportToPlaceInstance(tonumber(self.PlaceId), jobId, LocalPlayer)
        end)
        if teleported then
            return true
        end
    end

    local teleported = pcall(function()
        TeleportService:Teleport(tonumber(self.PlaceId), LocalPlayer)
    end)
    if not teleported then self.ActionInProgress = false end
    return teleported
end

function Updater:Check()
    if self.Destroyed or self.PendingUpdate or self.ActionInProgress then
        return
    end

    local ok, info = self:FetchVersion()
    if not ok or self.Destroyed then return end

    local startupAge = os_clock() - self.StartedAt

    if not self.CurrentVersion then
        self.CurrentVersion = info.Version
        self.CurrentCommit = info.Commit
        return
    end

    if info.Version == self.CurrentVersion then
        return
    end

    if startupAge < self.StartupGrace then
        self.CurrentVersion = info.Version
        self.CurrentCommit = info.Commit
        return
    end

    if self.CancelledVersions[info.Version] or self.RejectedVersions[info.Version] then
        return
    end

    if not self:ValidateBackendChange(info) then
        self.RejectedVersions[info.Version] = true
        return
    end

    if not self.Destroyed then self.PendingUpdate = info end
end

function Updater:Start()
    if self.Destroyed or self.Started then return false end
    self.Started = true

    task.spawn(function()
        task.wait(5)
        if self.Destroyed then
            return
        end

        self:Check()

        while not self.Destroyed do
            task.wait(self.PollInterval * (1 + (math.random() * 2 - 1) * 0.15))
            if not self.Destroyed then
                self:Check()
            end
        end
    end)
end

function Updater:Destroy()
    if self.Destroyed then
        return
    end

    self.Destroyed = true
    self.Started = false
    self.PendingUpdate = nil
end

return Updater


]],
    ["src/frontend/init.lua"] = [[
-- DepHub panel library.
--
-- Faithful Luau port of the authored interface mockup (proposta-02.html +
-- dephub.css). It rebuilds the same monochrome window with Roblox GUI
-- instances: the fixed 840x560 shell, the draggable header with the brand mark,
-- the current-game caption, the three macOS-style window buttons, the 160px
-- section nav, per-page headings, the search field, and the full control set
-- (field, toggle, checkbox, range, input group, choice trigger, colour trigger,
-- action, keybind, notice, collapsible, button group), plus the toast and the
-- confirmation dialog.
--
-- The library is pure presentation: callers hand it a spec and receive
-- callbacks. src/core/panel-host.lua binds those callbacks to a backend.
--
-- The ScreenGui is named with "dephub" so src/core/ui-guard keeps it enabled,
-- on top and parented to gethui().
--
-- Modules load as plain chunks (no require), so the theme tokens below are
-- inlined; src/frontend/theme.lua mirrors the same values as the reference.

