        Size = Theme.px(Theme.MarkSize),
        Parent = brand,
    })
    corner(mark, Theme.MarkRadius)
    -- The mark holds the DepHub "D" glyph (the mockup's inline SVG, drawn as text).
    label(new("TextLabel", {
