        Name = "Nav",
        BackgroundColor3 = Theme.Color(Theme.NavBg),
        BorderSizePixel = 0,
        Size = UDim2.new(0, Theme.NavWidth, 1, 0),
        Parent = layout,
    })
    new("Frame", {
        Name = "Divider",
        BackgroundColor3 = Theme.Color(Theme.NavBorder),
        BorderSizePixel = 0,
        Size = UDim2.new(0, 1, 1, 0),
        Position = UDim2.new(1, -1, 0, 0),
        Parent = nav,
    })
    local navList = new("Frame", {
        Name = "List",
