    ["src/games/aotr.lua"] = [[
-- AOT:R module: defensive client-side features. No external webhooks.
local Players=game:GetService("Players")
local Workspace=game:GetService("Workspace")
local TweenService=game:GetService("TweenService")
local player=Players.LocalPlayer
local env=type(getgenv)=="function" and getgenv() or _G
local old=env.__DEPHUB_AOTR
if type(old)=="table" and type(old.Destroy)=="function" then pcall(old.Destroy,old) end
-- Humanised timing: vary the refresh interval so the loop is not perfectly periodic.
local function jitter(base, spread)
 spread = spread or 0.15
 return task.wait(base * (1 + (math.random() * 2 - 1) * spread))
end
local M={Destroyed=false,Toggles={TitanESP=false,NapeVisible=false,NapeExtend=false,ErenExtend=false,AutoBladeRefill=false,AutoGrabEscape=false,AntiInjury=false,AutoRetry=false,AntiAFK=false},Values={NapeMultiplier=1},Connections={},Originals={},Highlights={},LastError="none"}
local function warnError(message)
 local nextError=tostring(message)
 if M.LastError~=nextError then warn("[DepHub/AOTR] "..nextError) end
 M.LastError=nextError
end
local base=(env.__DEPHUB or {}).SourceBaseURL or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"
local okHelpers,helpers=pcall(function()
 local source=__dephubHttpGet(base.."src/games/features/aotr/assistance.lua")
 local chunk,err=loadstring(source)
 assert(chunk,err)
 return chunk().new({Player=player,Warn=warnError})
end)
if okHelpers and type(helpers)=="table" then M.Assistance=helpers else warnError("Assistance unavailable: "..tostring(helpers)) end
local function child(parent,name) return parent and parent:FindFirstChild(name) end
local function descendants(parent,name)
 if not parent then return nil end
 return parent:FindFirstChild(name,true)
end
local function character() return player and player.Character end
local function main() return child(character(),"Main") end
local function remote(name)
 local assets=child(game:GetService("ReplicatedStorage"),"Assets")
 return child(child(assets,"Remotes"),name)
end
local function titanFolder() return child(Workspace,"Titans") end
local function titans()
 local result={}
 local folder=titanFolder()
 if folder then
  for _,model in ipairs(folder:GetChildren()) do
   if model:IsA("Model") and child(model,"Hitboxes") then result[#result+1]=model end
  end
 end
 return result
end
local function nape(model)
 return child(child(child(model,"Hitboxes"),"Hit"),"Nape")
end
local function remember(part)
 if not M.Originals[part] then
  M.Originals[part]={Size=part.Size,Transparency=part.Transparency}
 end
end
local function restore()
 for part,values in pairs(M.Originals) do
  if part and part.Parent then
   pcall(function() part.Size=values.Size;part.Transparency=values.Transparency end)
  end
 end
 M.Originals={}
end
function M:Refresh()
 if self.Destroyed then return end
 local desired={}
 for _,model in ipairs(titans()) do
  local part=nape(model)
  if part and part:IsA("BasePart") then
   if self.Toggles.NapeVisible or self.Toggles.NapeExtend then
    desired[part]=true
    remember(part)
    local original=self.Originals[part]
    part.Transparency=self.Toggles.NapeVisible and 0.65 or original.Transparency
    part.Size=self.Toggles.NapeExtend and original.Size*(self.Values.NapeMultiplier or 1) or original.Size
   elseif self.Originals[part] then
    local original=self.Originals[part]
    part.Size=original.Size;part.Transparency=original.Transparency
    self.Originals[part]=nil
   end
  end
  if model.Name=="Attack_Titan" and self.Toggles.ErenExtend then
   local marker=child(model,"Marker")
   local hit=child(child(model,"Hitboxes"),"Hit")
   local target=marker and (marker:IsA("Highlight") or marker:IsA("BillboardGui") or marker:IsA("SelectionBox")) and marker.Adornee
   if target and hit and target:IsA("BasePart") and target:IsDescendantOf(hit) then
    remember(target);desired[target]=true
    target.Size=Vector3.new(95,95,95);target.Transparency=0.94
   end
  end
  local highlight=self.Highlights[model]
  if self.Toggles.TitanESP then
   if not highlight or not highlight.Parent then
    highlight=Instance.new("Highlight")
    highlight.Name="DepHub_TitanESP"
    highlight.Adornee=model
    highlight.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
    highlight.FillTransparency=0.7
    highlight.OutlineTransparency=0
    highlight.Parent=model
    self.Highlights[model]=highlight
   end
  elseif highlight then highlight:Destroy();self.Highlights[model]=nil end
 end
 for part,original in pairs(self.Originals) do
  if not desired[part] then
   if part.Parent then
    local ok,err=pcall(function() part.Size=original.Size;part.Transparency=original.Transparency end)
    if not ok then warnError(err) end
   end
   self.Originals[part]=nil
  end
 end
 for model,highlight in pairs(self.Highlights) do
  if model.Parent~=titanFolder() or not self.Toggles.TitanESP then
   pcall(function() highlight:Destroy() end);self.Highlights[model]=nil
  end
 end
end
function M:SetToggle(name,value)
 if self.Destroyed or self.Toggles[name]==nil then return false end
 value=value==true
 if self.Toggles[name]==value then return true end
 if name=="AutoBladeRefill" or name=="AutoGrabEscape" or name=="AntiInjury" or name=="AutoRetry" or name=="AntiAFK" then
  if not self.Assistance then warnError("Assistance module unavailable");return false end
  if not self.Assistance:SetToggle(name,value) then return false end
 end
 self.Toggles[name]=value==true
 local ok,err=pcall(function() self:Refresh() end)
 if not ok then warnError(err) end
 return true
end
function M:GetToggle(name) return self.Toggles[name]==true end
function M:SetNapeMultiplier(value)
 value=tonumber(value)
 if self.Destroyed or not value or value~=value or value<0 or value>2 then return false end
 self.Values.NapeMultiplier=value;self:Refresh();return true
end
function M:FindRefill()
 for _,rootName in ipairs({"Unclimbable","Climbable"}) do
  local root=child(Workspace,rootName)
  if root then
   for _,item in ipairs(root:GetDescendants()) do
    if item.Name=="Refill" and item:IsA("BasePart") then
     local ancestor=item.Parent
     while ancestor and ancestor~=root do
      if ancestor.Name=="GasTanks" then return item end
      ancestor=ancestor.Parent
     end
    end
   end
  end
 end
 return nil
end
function M:TeleportToRefill()
 if self.Destroyed then return false end
 local root=child(character(),"HumanoidRootPart")
 local refill=self:FindRefill()
 if not root or not root:IsA("BasePart") or not refill then warnError("Root or GasTanks.Refill unavailable");return false end
 self:CancelTeleport()
 local distance=(root.Position-refill.Position).Magnitude
 local tween=TweenService:Create(root,TweenInfo.new(math.max(0.1,distance/225),Enum.EasingStyle.Linear),{CFrame=refill.CFrame+Vector3.new(0,3,0)})
 tween:Play()
 self.TeleportTween=tween
 return true
end
function M:CancelTeleport()
 if self.TeleportTween then self.TeleportTween:Cancel();self.TeleportTween=nil end
 return true
end
function M:GetStatus()
 local top=child(child(child(child(player,"PlayerGui"),"Interface"),"HUD"),"Main")
 top=child(top,"Top")
 local hotbar=child(child(top,"7"),"Hotbar")
 local assistance=""
 if self.Assistance then
  for _,name in ipairs({"AutoBladeRefill","AutoGrabEscape","AntiInjury","AutoRetry","AntiAFK"}) do
   if self.Toggles[name] then assistance=assistance.."\n"..name..": "..tostring(self.Assistance.States[name] or "starting") end
  end
 end
 return "PlaceId: "..tostring(game.PlaceId).." | GameId: "..tostring(game.GameId).."\ntitans: "..tostring(#titans())..
  "\nhotbar: "..(hotbar and "found" or "missing")..
  "\nrefill: "..(self:FindRefill() and "found" or "missing")..
  "\nblade hud: "..(descendants(top,"Blade") and "found" or "missing")..
  "\nlast error: "..self.LastError..assistance
end
function M:Destroy()
 if self.Destroyed then return end
 self.Destroyed=true
 if self.RefreshTask then pcall(task.cancel,self.RefreshTask);self.RefreshTask=nil end
 self:CancelTeleport()
 if self.Assistance then self.Assistance:Destroy() end
 for _,connection in ipairs(self.Connections) do pcall(function() connection:Disconnect() end) end
 for _,highlight in pairs(self.Highlights) do pcall(function() highlight:Destroy() end) end
 restore()
 self.Highlights={}
 if env.__DEPHUB_AOTR==self then env.__DEPHUB_AOTR=nil end
 if env.__DEPHUB and env.__DEPHUB.AOTR==self then env.__DEPHUB.AOTR=nil end
end
-- Refresh on newly spawned titans without touching unrelated Highlight children.
M.Connections[#M.Connections+1]=player.CharacterRemoving:Connect(function() M:CancelTeleport() end)
M.RefreshTask=task.spawn(function()
 while not M.Destroyed do
  jitter(1)
  if M.Destroyed then return end
  local ok,err=pcall(function() M:Refresh() end)
  if not ok then warnError(err) end
 end
end)
env.__DEPHUB_AOTR=M
env.__DEPHUB=env.__DEPHUB or {}
env.__DEPHUB.AOTR=M
return M

]],
    ["src/games/bloxfruits.lua"] = [[
local game = game
local task = task
local type = type
local tonumber = tonumber
local tostring = tostring
local pcall = pcall
local pairs = pairs
local ipairs = ipairs
local string_sub = string.sub
local string_lower = string.lower
local math_floor = math.floor

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Teams = game:GetService("Teams")
local Workspace = game:GetService("Workspace")
local LocalPlayer = Players.LocalPlayer
local Remotes = ReplicatedStorage:FindFirstChild("Remotes")
local ChangeSetting = Remotes and Remotes:FindFirstChild("ChangeSetting")
local Pirates = Teams:FindFirstChild("Pirates")
local Marines = Teams:FindFirstChild("Marines")
local Effect = ReplicatedStorage:FindFirstChild("Effect")
local EffectContainer = Effect and Effect:FindFirstChild("Container")
local Ice1 = EffectContainer and EffectContainer:FindFirstChild("Ice1")
local Waterwalk = Ice1 and Ice1:FindFirstChild("Waterwalk")
local IceEffect = Waterwalk and Waterwalk:FindFirstChild("ice")
local NPCs = ReplicatedStorage:FindFirstChild("NPCs")
local LegendarySwordDealer = NPCs and NPCs:FindFirstChild("Legendary Sword Dealer")

local env = type(getgenv) == "function" and getgenv() or _G
local STATE_KEY = "__DEPHUB_BLOXFRUITS"
local BASE_URL = ((type(getgenv)=="function" and getgenv() or _G).__DEPHUB or {}).SourceBaseURL or "https://raw.githubusercontent.com/glowpkj/DepHub/main/"
local VERSION = "0.0.3"
local previous = type(env[STATE_KEY]) == "table" and env[STATE_KEY] or nil
if previous and type(previous.Destroy) == "function" then pcall(previous.Destroy, previous) end

local function connect(list, signal, callback)
    if not signal then return nil end
    local ok, connection = pcall(signal.Connect, signal, callback)
    if ok and connection then
        list[#list + 1] = connection
        return connection
    end
end

local function disconnectAll(list)
    if not list then return end
    for index = #list, 1, -1 do
        local connection = list[index]
        list[index] = nil
        if connection then pcall(connection.Disconnect, connection) end
    end
end

local function destroy(instance)
    if instance then pcall(instance.Destroy, instance) end
end

local function getRoot(character)
    if not character then return nil end
    local root = character:FindFirstChild("HumanoidRootPart")
    if root and root:IsA("BasePart") then return root end
    local head = character:FindFirstChild("Head")
    if head and head:IsA("BasePart") then return head end
    return character:FindFirstChildWhichIsA("BasePart", true)
end

local function getPlayer(character)
    if not character then return nil end
    return Players:GetPlayerFromCharacter(character) or Players:FindFirstChild(character.Name)
end

local function getHumanoid(character)
    return character and character:FindFirstChildOfClass("Humanoid")
end

local function healthText(humanoid)
    if not humanoid then return "Vida: --/--" end
    local health = tonumber(humanoid.Health)
    local maxHealth = tonumber(humanoid.MaxHealth)
    if not health or not maxHealth then return "Vida: --/--" end
    return "Vida: " .. tostring(math_floor(health + 0.5)) .. "/" .. tostring(math_floor(maxHealth + 0.5))
end

local function isProtectionName(name)
    if type(name) ~= "string" then return false end
    local lowered = string_lower(name)
    return lowered == "pvpdisabled" or lowered == "pvpdisabledvalue" or lowered == "pvpprotection" or lowered == "protection" or lowered == "protected" or lowered == "safezone" or lowered == "nopvp" or string_sub(lowered, 1, 8) == "protect_"
end

local function hasProtection(character)
    if not character then return false end
    if character:FindFirstChildOfClass("ForceField") then return true end
    for _, name in ipairs({"PvPDisabled", "PVPDisabled", "PvPProtection", "Protection", "Protected", "SafeZone", "NoPvP"}) do
        if character:GetAttribute(name) == true then return true end
    end
    for _, object in ipairs(character:GetDescendants()) do
        if isProtectionName(object.Name) then
            if object:IsA("BoolValue") and object.Value then return true end
            if (object:IsA("IntValue") or object:IsA("NumberValue")) and object.Value ~= 0 then return true end
            if object:IsA("ObjectValue") and object.Value ~= nil then return true end
        end
    end
    return false
end

local function teamColor(player)
    if player and player.Team == Pirates then return BrickColor.new("Persimmon").Color end
    if player and player.Team == Marines then return BrickColor.new("Pastel light blue").Color end
    return BrickColor.new("Institutional white").Color
end

local function compile(source)
    if type(loadstring) ~= "function" then return false, "loadstring indisponivel" end
    local ok, chunk, compileError = pcall(loadstring, source)
    if not ok or type(chunk) ~= "function" then return false, tostring(compileError or chunk) end
    return true, chunk
end

local function loadModule(path, context)
    local okGet, source = pcall(function() return __dephubHttpGet(BASE_URL .. path) end)
    if not okGet or type(source) ~= "string" or #source == 0 then return false, tostring(source) end
    local okCompile, chunk = compile(source)
    if not okCompile then return false, chunk end
    local okRun, factory = pcall(chunk)
    if not okRun or type(factory) ~= "table" or type(factory.new) ~= "function" then return false, tostring(factory) end
    local okNew, module = pcall(factory.new, context)
    if not okNew or type(module) ~= "table" then return false, tostring(module) end
    return true, module
end

local baseContext = {LocalPlayer = LocalPlayer, Players = Players, Workspace = Workspace, Connect = connect, DisconnectAll = disconnectAll, Destroy = destroy, GetRoot = getRoot, GetPlayer = getPlayer, GetHumanoid = getHumanoid, HealthText = healthText, IsProtectionName = isProtectionName, HasProtection = hasProtection, TeamColor = teamColor, ChangeSetting = ChangeSetting}
local configOk, config = loadModule("src/games/features/bloxfruits/config.lua", baseContext)
if not configOk then return false end
config:Load({PlayerESP = false, FruitESP = false, UnbreakableAll = false, DashCustomizer = false, FlashstepNoCooldown = false, WaterWalking = false, AutoJoinTeam = true, DashLength = 1, PreferredTeam = "Pirates", BladeHits = false, AutoFarm = false})

-- Pure-data quest/rarity tables. Loaded separately because quests.lua returns a
-- plain table, not a feature factory (no .new).
local function loadData(path)
    local okGet, source = pcall(function() return __dephubHttpGet(BASE_URL .. path) end)
    if not okGet or type(source) ~= "string" or #source == 0 then return nil end
    local okCompile, chunk = compile(source)
    if not okCompile then return nil end
    local okRun, data = pcall(chunk)
    if not okRun or type(data) ~= "table" then return nil end
    return data
end
local questData = loadData("src/games/features/bloxfruits/quests.lua")

local State = {
    Started = false,
    Destroyed = false,
    Config = config,
    Version = VERSION,
    Toggles = {
        ObservationHaki = true,
        PlayerESP = config:Get("PlayerESP", false),
        FruitESP = config:Get("FruitESP", false),
        UnbreakableAll = config:Get("UnbreakableAll", false),
        DashCustomizer = config:Get("DashCustomizer", false),
        FlashstepNoCooldown = config:Get("FlashstepNoCooldown", false),
        WaterWalking = config:Get("WaterWalking", false),
        AutoJoinTeam = config:Get("AutoJoinTeam", true),
        BladeHits = config:Get("BladeHits", false),
        AutoFarm = config:Get("AutoFarm", false)
    },
    Values = {DashLength = tonumber(config:Get("DashLength", 1)) or 1},
    Connections = {},
    PlayerESP = {},
    FruitESP = {},
    OriginalUnbreakableAll = nil,
    UnbreakableCaptured = false,
    CameraShakeDisabled = false,
    Paths = {IceEffect = IceEffect, LegendarySwordDealer = LegendarySwordDealer, IceEffectPath = "game:GetService(\"ReplicatedStorage\").Effect.Container.Ice1.Waterwalk.ice", LegendarySwordDealerPath = "game:GetService(\"ReplicatedStorage\").NPCs[\"Legendary Sword Dealer\"]"},
    QuestData = questData,
    FruitRarityFilter = {Enabled = false, Common = false, Uncommon = false, Rare = false, Legendary = false, Mythical = true}
}

baseContext.State = State
env[STATE_KEY] = State
env.__DEPHUB = env.__DEPHUB or {}
env.__DEPHUB.BloxFruits = State
env.__DEPHUB.BloxFruitsPaths = State.Paths

local featurePaths = {PlayerESP = "src/games/features/bloxfruits/playeresp.lua", FruitESP = "src/games/features/bloxfruits/fruit.lua", ObservationHaki = "src/games/features/bloxfruits/observation.lua", UnbreakableAll = "src/games/features/bloxfruits/unbreakable.lua", CameraShake = "src/games/features/bloxfruits/camerashake.lua", DashCustomizer = "src/games/features/bloxfruits/dash.lua", FlashstepNoCooldown = "src/games/features/bloxfruits/flashstep.lua", WaterWalking = "src/games/features/bloxfruits/waterwalking.lua", AutoJoinTeam = "src/games/features/bloxfruits/team.lua", BladeHits = "src/games/features/bloxfruits/bladhits.lua", AutoFarm = "src/games/features/bloxfruits/autofarm.lua"}
featurePaths.FruitVFX = "src/games/features/bloxfruits/fruitvfx.lua"
local features = {}
for name, path in pairs(featurePaths) do
    local ok, feature = loadModule(path, baseContext)
    if not ok then
        for _, loaded in pairs(features) do pcall(loaded.Destroy, loaded) end
        pcall(config.Destroy, config)
        if env[STATE_KEY] == State then env[STATE_KEY] = nil end
        if env.__DEPHUB and env.__DEPHUB.BloxFruits == State then env.__DEPHUB.BloxFruits = nil end
        return false
    end
    features[name] = feature
end

State.Features = features
State.PlayerESP = features.PlayerESP.Records
State.FruitESP = features.FruitESP.Records

function State:RemovePlayerESP(character)
    local feature = self.Features and self.Features.PlayerESP
    if feature and type(feature._remove) == "function" then feature:_remove(character) end
end

function State:RemoveFruitESP(tool)
    local feature = self.Features and self.Features.FruitESP
    if feature and type(feature._remove) == "function" then feature:_remove(tool) end
end

function State:SetCameraShake(enabled)
    if self.Destroyed then return false end
    return self.Features.CameraShake:SetEnabled(enabled == true)
end

function State:SetDashLength(value)
    if self.Destroyed or not self.Features or not self.Features.DashCustomizer then return false end
    local ok = self.Features.DashCustomizer:SetValue(value)
    if ok then self.Values.DashLength = self.Features.DashCustomizer:GetValue() end
    return ok
end

function State:GetDashLength()
    return self.Values.DashLength
end

function State:SetPreferredTeam(team)
    if self.Destroyed or not self.Features or not self.Features.AutoJoinTeam then return false end
    return self.Features.AutoJoinTeam:SetTeam(team)
end

function State:GetPreferredTeam()
    return self.Features and self.Features.AutoJoinTeam and self.Features.AutoJoinTeam.PreferredTeam or self.Config:Get("PreferredTeam", "Pirates")
end

function State:SetBladeRange(value)
    if self.Destroyed or not self.Features or not self.Features.BladeHits then return false end
    return self.Features.BladeHits:SetRange(value)
end

function State:SetFruitRarity(rarity, enabled)
    if self.Destroyed or type(rarity) ~= "string" then return false end
    if self.FruitRarityFilter[rarity] == nil then return false end
    self.FruitRarityFilter[rarity] = enabled == true
    return true
end

function State:SetFruitRarityFilter(enabled)
    if self.Destroyed then return false end
    self.FruitRarityFilter.Enabled = enabled == true
    return true
end

function State:GetFarmStatus()
    local feature = self.Features and self.Features.AutoFarm
    return feature and feature:GetStatus() or nil
end

function State:SaveConfig()
    if self.Destroyed then return false end
    return self.Config:Update({PlayerESP = self.Toggles.PlayerESP, FruitESP = self.Toggles.FruitESP, UnbreakableAll = self.Toggles.UnbreakableAll, DashCustomizer = self.Toggles.DashCustomizer, FlashstepNoCooldown = self.Toggles.FlashstepNoCooldown, WaterWalking = self.Toggles.WaterWalking, AutoJoinTeam = self.Toggles.AutoJoinTeam, BladeHits = self.Toggles.BladeHits, AutoFarm = self.Toggles.AutoFarm, DashLength = self.Values.DashLength, PreferredTeam = self:GetPreferredTeam()})
end

function State:SetToggle(name, enabled)
    if self.Destroyed or type(name) ~= "string" then return false end
    enabled = enabled == true
    if self.Toggles[name] == enabled then
        self:SaveConfig()
        return true
    end
    local feature = self.Features[name]
    if not feature then return false end
    local ok = enabled and feature:Enable() or feature:Disable()
    if ok == false then return false end
    self.Toggles[name] = enabled
    if name == "UnbreakableAll" then
        self.UnbreakableCaptured = feature.Captured == true
        self.OriginalUnbreakableAll = feature.Original
    end
    self:SaveConfig()
    return true
end

function State:GetToggle(name)
    return self.Toggles[name] == true
end

function State:GetPaths()
    return self.Paths
end

function State:_reapplyCharacter(character)
    if self.Destroyed or not character then return end
    task.defer(function()
        if self.Destroyed then return end
        for _, feature in pairs(self.Features or {}) do
            if feature.Enabled and type(feature._bind) == "function" then
                pcall(feature._bind, feature, character)
            end
        end
    end)
end

function State:Destroy()
    if self.Destroyed then return end
    self:SaveConfig()
    self.Destroyed = true
    for name in pairs(self.Toggles) do self.Toggles[name] = false end
    for _, feature in pairs(self.Features or {}) do pcall(feature.Destroy, feature) end
    pcall(config.Destroy, config)
    disconnectAll(self.Connections)
    self.Features = nil
    if env[STATE_KEY] == self then env[STATE_KEY] = nil end
    if env.__DEPHUB and env.__DEPHUB.BloxFruits == self then env.__DEPHUB.BloxFruits = nil end
end

function State:Start()
    if self.Destroyed or self.Started then return false end
    self.Started = true
    if self.Toggles.ObservationHaki then self.Features.ObservationHaki:Enable() end
    for _, name in ipairs({"PlayerESP", "FruitESP", "UnbreakableAll", "DashCustomizer", "FlashstepNoCooldown", "WaterWalking", "BladeHits", "AutoFarm"}) do
        if self.Toggles[name] then
            local ok = self.Features[name]:Enable()
            if not ok then self.Toggles[name] = false end
        end
    end
    if self.Toggles.AutoJoinTeam then
        local ok = self.Features.AutoJoinTeam:Enable()
        if not ok then self.Toggles.AutoJoinTeam = false end
    end
    connect(self.Connections, LocalPlayer.CharacterAdded, function(character)
        self:_reapplyCharacter(character)
    end)
    return true
end

if not LocalPlayer then return false end
local ok, started = pcall(State.Start, State)
if not ok or not started then
    pcall(State.Destroy, State)
    return false
end
return State


]],
    ["src/games/features/aotr/assistance.lua"] = [[
-- Optional helpers adapted from aotr_corrigido_v3. Paths remain runtime assumptions.
local Feature = {}
function Feature.new(context)
    local self = {Jobs = {}, States = {}, Injuries = {}, Destroyed = false}
    local player = context.Player
    local function path(root, ...)
        for _, name in ipairs({...}) do root = root and root:FindFirstChild(name) end
        return root
    end
    local function report(name, message)
        self.States[name] = tostring(message)
        context.Warn(name .. ": " .. tostring(message))
    end
    local function stop(name)
        local job = self.Jobs[name]
        self.Jobs[name] = nil
        if job then
            job.Active = false
            if job.Connection then job.Connection:Disconnect() end
            if job.Thread then pcall(task.cancel, job.Thread) end
        end
    end
    local function restoreInjuries()
        for injury, entry in pairs(self.Injuries) do
            -- Do not put injuries from a previous character into the new character.
            if entry.Character == player.Character and entry.Parent.Parent then
                local ok, err = pcall(function() injury.Parent = entry.Parent end)
                if not ok then report("AntiInjury", err) end
            else pcall(function() injury:Destroy() end) end
        end
        self.Injuries = {}
    end
    local function invoke(...)
        local remote = path(game:GetService("ReplicatedStorage"), "Assets", "Remotes", "GET")
        if not remote or not remote:IsA("RemoteFunction") then error("Assets.Remotes.GET unavailable") end
        return remote:InvokeServer(...)
    end
    local function top()
        return path(player, "PlayerGui", "Interface", "HUD", "Main", "Top")
    end
    local function visible(gui)
        if not gui or not gui:IsA("GuiObject") then return false end
        local item = gui
        while item and item ~= player do
            if item:IsA("GuiObject") and not item.Visible then return false end
            if item:IsA("ScreenGui") and not item.Enabled then return false end
            item = item.Parent
        end
        return true
    end
    local ticks = {}
    function ticks.AutoBladeRefill(job)
        local character = player.Character
        local blade = path(character, "Rig_" .. player.Name, "LeftHand", "Blade_1")
        if not blade or not blade:IsA("BasePart") then return "waiting: Rig/LeftHand/Blade_1" end
        if blade.Transparency ~= 1 then job.Reloading = nil; return "blade equipped" end
        if character:GetAttribute("IFrames") ~= nil then return "waiting: IFrames" end
        local hud = top()
        local sets = path(hud and hud:FindFirstChild("Blade", true), "Sets")
        if not sets or not (sets:IsA("TextLabel") or sets:IsA("TextButton")) then return "waiting: Blade.Sets" end
        local available = tonumber(sets.Text:match("(%d+)%s*/"))
        if not available or available <= 0 then return "no blade sets / unreadable HUD" end
        if job.Character ~= character then job.Character = character; job.Reloading = nil end
        job.Reloading = job.Reloading or os.clock()
        if os.clock() - job.Reloading >= 30 then return "reload timeout; toggle off/on to retry" end
        invoke("Blades", "Reload")
        return "reload requested (unverified)"
    end
    function ticks.AntiInjury()
        local folder = path(player.Character, "Injuries")
        if not folder then return "waiting: Character.Injuries" end
        for _, injury in ipairs(folder:GetChildren()) do
            self.Injuries[injury] = {Parent = folder, Character = player.Character}
            injury.Parent = nil -- retained for restoration; never destroy current injuries
        end
        for injury, entry in pairs(self.Injuries) do
            if entry.Character ~= player.Character then
                pcall(function() injury:Destroy() end)
                self.Injuries[injury] = nil
            end
        end
        return "client injuries detached; server effect unverified"
    end
    function ticks.AutoGrabEscape(job)
        local buttons = path(player, "PlayerGui", "Interface", "Buttons")
        if not buttons then return "waiting: Interface.Buttons" end
        if job.Folder ~= buttons then
            if job.Connection then job.Connection:Disconnect() end
            job.Folder = buttons
            job.Connection = buttons.ChildAdded:Connect(function()
                if not job.Active or self.Destroyed then return end
                local ok, err = pcall(function()
                    local remote = path(game:GetService("ReplicatedStorage"), "Assets", "Remotes", "POST")
                    if not remote or not remote:IsA("RemoteEvent") then error("Assets.Remotes.POST unavailable") end
                    remote:FireServer("Attacks", "Slash_Escape")
                end)
                if not ok then report("AutoGrabEscape", err) end
            end)
        end
        return "listening: Buttons.ChildAdded (legacy trigger)"
    end
    function ticks.AutoRetry(job)
        local title = path(player, "PlayerGui", "Interface", "Rewards", "Main", "Info", "Main", "Buttons", "Retry", "Title")
        if not visible(title) or not (title:IsA("TextLabel") or title:IsA("TextButton")) then job.Requested = nil; return "waiting: visible Retry.Title" end
        if title.Text:find("STARTING", 1, true) or title.Text:find("(0/0)", 1, true) then job.Requested=nil; return "waiting: retry state" end
        if job.Requested == title then return "retry requested; waiting for next rewards screen" end
        invoke("Functions", "Retry", "Add")
        job.Requested = title
        return "retry requested (unverified)"
    end
    function self:SetToggle(name, enabled)
        if self.Destroyed then return false end
        if not ticks[name] and name ~= "AntiAFK" then return false end
        stop(name)
        if name == "AntiInjury" and not enabled then restoreInjuries() end
        self.States[name] = enabled and "starting" or "off"
        if not enabled then return true end
        local job = {Active = true}
        self.Jobs[name] = job
        if name == "AntiAFK" then
            job.Connection = player.Idled:Connect(function()
                if not job.Active or self.Destroyed then return end
                local ok, err = pcall(function()
                    local virtualUser = game:GetService("VirtualUser")
                    virtualUser:CaptureController()
                    virtualUser:ClickButton2(Vector2.new())
                end)
                if not ok then report(name, err) end
            end)
            self.States[name] = "listening: Idled"
        else
            job.Thread = task.spawn(function()
                while job.Active and not self.Destroyed do
                    local ok, status = pcall(ticks[name], job)
                    if not job.Active or self.Destroyed then return end
                    if ok then self.States[name] = status else report(name, status) end
                    task.wait(name == "AutoBladeRefill" and 1 or 0.5)
                end
            end)
        end
        return true
    end
    function self:Destroy()
        if self.Destroyed then return end
        self.Destroyed = true
        for name in pairs(self.Jobs) do stop(name) end
        restoreInjuries()
    end
    return self
end
return Feature

