    ["src/games/features/bloxfruits/config.lua"] = [[
local HttpService = game:GetService("HttpService")

local Feature = {}
Feature.__index = Feature

local function funcs()
    return {
        read = type(readfile) == "function" and readfile or nil,
        write = type(writefile) == "function" and writefile or nil,
        exists = type(isfile) == "function" and isfile or nil
    }
end

function Feature.new(context)
    local self = setmetatable({}, Feature)
    self.Context = context
    self.Enabled = true
    self.Data = {}
    self.FileName = "DepHub_BloxFruits_" .. tostring(game.GameId) .. ".json"
    self.MemoryKey = "__DEPHUB_BLOXFRUITS_CONFIG"
    return self
end

function Feature:Load(defaults)
    self.Data = {}
    for key, value in pairs(defaults or {}) do self.Data[key] = value end
    local f = funcs()
    local env = type(getgenv) == "function" and getgenv() or _G
    local loaded
    if f.read and f.exists then
        local okExists, exists = pcall(f.exists, self.FileName)
        if okExists and exists then
            local okRead, source = pcall(f.read, self.FileName)
            if okRead and type(source) == "string" and source ~= "" then
                local okDecode, data = pcall(HttpService.JSONDecode, HttpService, source)
                if okDecode and type(data) == "table" then loaded = data end
            end
        end
    end
    if not loaded and type(env[self.MemoryKey]) == "table" then loaded = env[self.MemoryKey] end
    if type(loaded) == "table" then
        for key, value in pairs(loaded) do self.Data[key] = value end
    end
    env[self.MemoryKey] = self.Data
    return self.Data
end

function Feature:Get(key, fallback)
    local value = self.Data[key]
    if value == nil then return fallback end
    return value
end

function Feature:Set(key, value, save)
    self.Data[key] = value
    local env = type(getgenv) == "function" and getgenv() or _G
    env[self.MemoryKey] = self.Data
    if save ~= false then self:Save() end
    return true
end

function Feature:Update(values, save)
    for key, value in pairs(values or {}) do self.Data[key] = value end
    local env = type(getgenv) == "function" and getgenv() or _G
    env[self.MemoryKey] = self.Data
    if save ~= false then self:Save() end
    return true
end

function Feature:Save()
    local f = funcs()
    if not f.write then return false end
    local okEncode, source = pcall(HttpService.JSONEncode, HttpService, self.Data)
    if not okEncode or type(source) ~= "string" then return false end
    return pcall(f.write, self.FileName, source)
end

function Feature:Enable() return true end
function Feature:Disable() return true end
function Feature:IsEnabled() return true end
function Feature:Destroy()
    self:Save()
    self.Context = nil
end

return Feature

]],
    ["src/games/features/bloxfruits/dash.lua"] = [[
local Feature = {}
Feature.__index = Feature

local function clamp(value)
    value = tonumber(value) or 1
    if value < 1 then return 1 end
    if value > 100 then return 100 end
    return math.floor(value + 0.5)
end

function Feature.new(context)
    return setmetatable({
        Context = context,
        State = context.State,
        Enabled = false,
        Value = clamp(context.State.Values.DashLength),
        Character = nil,
        CharacterConnections = {},
        RespawnConnection = nil
    }, Feature)
end

function Feature:_disconnectCharacter()
    self.Context.DisconnectAll(self.CharacterConnections)
    self.Character = nil
end

function Feature:_apply(character)
    if not self.Enabled or not character or not character.Parent then return end
    local value = clamp(self.Value)
    pcall(function()
        if character:GetAttribute("DashLength") ~= value then character:SetAttribute("DashLength", value) end
        if character:GetAttribute("DashLengthAir") ~= value then character:SetAttribute("DashLengthAir", value) end
        if character:GetAttribute("DashLengthGround") ~= value then character:SetAttribute("DashLengthGround", value) end
    end)
end

function Feature:_bind(character)
    self:_disconnectCharacter()
    self.Character = character
    if not character then return end
    self:_apply(character)
    for _, name in ipairs({"DashLength", "DashLengthAir", "DashLengthGround"}) do
        self.Context.Connect(self.CharacterConnections, character:GetAttributeChangedSignal(name), function()
            self:_apply(character)
        end)
    end
end

function Feature:SetValue(value)
    self.Value = clamp(value)
    self.State.Values.DashLength = self.Value
    if self.Enabled then self:_apply(self.Character or self.Context.LocalPlayer.Character) end
    return true
end

function Feature:Enable()
    if self.Enabled or self.State.Destroyed then return true end
    self.Enabled = true
    self:_bind(self.Context.LocalPlayer.Character)
    self.RespawnConnection = self.Context.Connect({}, self.Context.LocalPlayer.CharacterAdded, function(character)
        if self.Enabled then self:_bind(character) end
    end)
    return true
end

function Feature:Disable()
    if not self.Enabled then return true end
    self.Enabled = false
    self:_disconnectCharacter()
    if self.RespawnConnection then
        pcall(self.RespawnConnection.Disconnect, self.RespawnConnection)
        self.RespawnConnection = nil
    end
    local character = self.Context.LocalPlayer.Character
    if character and character.Parent then
        pcall(function()
            character:SetAttribute("DashLength", 1)
            character:SetAttribute("DashLengthAir", 1)
            character:SetAttribute("DashLengthGround", 1)
        end)
    end
    return true
end

function Feature:IsEnabled() return self.Enabled end
function Feature:GetValue() return self.Value end

function Feature:Destroy()
