    ["src/games/features/bloxfruits/fruit.lua"] = [[
local game = game
local task = task
local pcall = pcall
local pairs = pairs
local ipairs = ipairs
local tostring = tostring
local string_lower = string.lower
local math_floor = math.floor

local GENERIC_NAMES = {Fruit = true, Handle = true, Weld = true, Welded = true, Keep = true, Script = true, LocalScript = true, ToolScript = true, FruitAnimator = true, EatRemote = true}
local WORLD_NON_ISLANDS = {Camera = true, Characters = true, _WorldOrigin = true, Map = true, Effects = true, Effect = true, Debris = true, Ignore = true, Temp = true, Temporary = true, SpawnLocation = true, Fruit = true}

-- Humanised timing: vary each periodic wait to avoid a perfectly periodic loop.
local function jitter(base, spread)
    spread = spread or 0.15
    return task.wait(base * (1 + (math.random() * 2 - 1) * spread))
end

local function safeText(value)
    if value == nil then return nil end
    local text = tostring(value)
    return text ~= "" and text or nil
end

local Feature = {}
Feature.__index = Feature

function Feature.new(context)
    return setmetatable({Context = context, State = context.State, Connections = {}, Records = {}, Enabled = false, Thread = nil}, Feature)
end

function Feature:_isDroppedTool(instance)
    return instance and instance:IsA("Tool") and instance.Parent == self.Context.Workspace and instance:FindFirstChild("Fruit") ~= nil
end

function Feature:_isSpawnedFruit(instance)
    return instance and instance:IsA("Model") and instance.Name == "Fruit" and not instance:FindFirstAncestorOfClass("Tool") and instance:IsDescendantOf(self.Context.Workspace)
end

function Feature:_isFruitSpawnEntry(instance)
    local worldOrigin = self.Context.Workspace:FindFirstChild("_WorldOrigin")
    local fruitSpawns = worldOrigin and worldOrigin:FindFirstChild("FruitSpawns")
    if not fruitSpawns or not instance or not instance:IsDescendantOf(fruitSpawns) then return false end
    if instance:IsA("Tool") then return instance:FindFirstChild("Fruit") ~= nil end
    return instance:IsA("Model") and instance.Name == "Fruit" and not instance:FindFirstAncestorOfClass("Tool")
end

function Feature:_isFruit(instance)
    return self:_isDroppedTool(instance) or self:_isSpawnedFruit(instance) or self:_isFruitSpawnEntry(instance)
end

function Feature:_fruitModel(instance)
    if not instance then return nil end
    if instance:IsA("Tool") then return instance:FindFirstChild("Fruit") end
    if instance:IsA("Model") then return instance end
end

function Feature:_adornee(instance)
    local fruit = self:_fruitModel(instance)
    if fruit and fruit:IsA("Model") then return fruit.PrimaryPart or fruit:FindFirstChildWhichIsA("BasePart", true) end
    if instance:IsA("Tool") then return instance:FindFirstChild("Handle") or instance:FindFirstChildWhichIsA("BasePart", true) end
    return fruit
end

function Feature:_position(instance, adornee)
    local fruit = self:_fruitModel(instance)
    if fruit and fruit:IsA("Model") then
        local ok, pivot = pcall(fruit.GetPivot, fruit)
        if ok and pivot then return pivot.Position end
    end
    if adornee and adornee:IsA("BasePart") then return adornee.Position end
    if adornee and adornee:IsA("Attachment") then return adornee.WorldPosition end
end

function Feature:_attribute(instance, name)
    local current = instance
    while current and current ~= self.Context.Workspace do
        local ok, value = pcall(current.GetAttribute, current, name)
        if ok and value ~= nil then return safeText(value) end
        current = current.Parent
    end
end

function Feature:_signature(adornee)
    local signatures = self.State and self.State.FruitSignatures
    if type(signatures) ~= "table" or not adornee then return nil end
    local meshId = nil
    local textureId = nil
    local mesh = adornee:FindFirstChildWhichIsA("SpecialMesh")
    if mesh then
        meshId = safeText(mesh.MeshId)
        textureId = safeText(mesh.TextureId)
    end
    if adornee:IsA("MeshPart") then
        meshId = meshId or safeText(adornee.MeshId)
        textureId = textureId or safeText(adornee.TextureID)
    end
    for fruitName, signature in pairs(signatures) do
        if type(signature) == "table" then
            local wantedMesh = safeText(signature.MeshId)
            local wantedTexture = safeText(signature.TextureId)
            if (wantedMesh and meshId == wantedMesh) or (wantedTexture and textureId == wantedTexture) then return safeText(fruitName) end
        elseif type(signature) == "string" and (signature == meshId or signature == textureId) then
            return safeText(fruitName)
        end
    end
end

function Feature:_fruitName(instance, adornee)
    local original = self:_attribute(instance, "OriginalName")
    if original and not GENERIC_NAMES[original] then return original end
    local fruit = self:_fruitModel(instance)
    if fruit then
        local value = self:_attribute(fruit, "OriginalName")
        if value and not GENERIC_NAMES[value] then return value end
    end
    local signature = self:_signature(adornee)
    if signature then return signature end
    if instance:IsA("Tool") then
        local name = safeText(instance.Name)
        if name and not GENERIC_NAMES[name] then return name end
    end
    if fruit and fruit:IsA("Model") then
        local name = safeText(fruit.Name)
        if name and not GENERIC_NAMES[name] then return name end
    end
    return "Fruit"
end

function Feature:_droppedBy(instance)
    local value = self:_attribute(instance, "DroppedBy")
    if value then return value end
    local fruit = self:_fruitModel(instance)
    return fruit and self:_attribute(fruit, "DroppedBy") or nil
end

function Feature:_getMap()
    return self.Context.Workspace:FindFirstChild("Map")
end

function Feature:_directMapModel(instance)
    local map = self:_getMap()
    local current = instance
    while map and current and current.Parent and current.Parent ~= map do current = current.Parent end
    if map and current and current.Parent == map and current:IsA("Model") then return current end
end

function Feature:_directWorldModel(instance)
    local map = self:_getMap()
    local current = instance
    while current and current.Parent do
        if current.Parent == self.Context.Workspace then
            return current:IsA("Model") and not WORLD_NON_ISLANDS[current.Name] and current or nil
        end
        if map and current.Parent == map then return nil end
        current = current.Parent
    end
end

function Feature:_nearestIsland(position)
    if not position then return nil end
    local candidates = {}
    local map = self:_getMap()
    if map then
        for _, island in ipairs(map:GetChildren()) do if island:IsA("Model") then candidates[#candidates + 1] = island end end
    end
    for _, object in ipairs(self.Context.Workspace:GetChildren()) do
        if object:IsA("Model") and not WORLD_NON_ISLANDS[object.Name] then candidates[#candidates + 1] = object end
    end
    local best, bestDistance = nil, math.huge
    for _, island in ipairs(candidates) do
        local ok, cf, size = pcall(island.GetBoundingBox, island)
        if ok and cf and size then
            local point = cf:PointToObjectSpace(position)
            local half = size * 0.5
            local clamped = Vector3.new(math.clamp(point.X, -half.X, half.X), math.clamp(point.Y, -half.Y, half.Y), math.clamp(point.Z, -half.Z, half.Z))
            local distance = (cf:PointToWorldSpace(clamped) - position).Magnitude
            if distance < bestDistance then bestDistance, best = distance, island end
        end
    end
    return best
end

function Feature:_islandName(instance, position)
    local direct = self:_directMapModel(instance) or self:_directWorldModel(instance) or self:_nearestIsland(position)
    return direct and direct.Name or "Desconhecida"
end

function Feature:_lineFor(record, position)
    local root = self.Context.GetRoot(self.Context.LocalPlayer.Character)
    if not root or not position or not record.Beam then return end
    if not record.RootAttachment or record.RootAttachment.Parent ~= root then
        self.Context.Destroy(record.RootAttachment)
        local attachment = Instance.new("Attachment")
        attachment.Name = "DepHubFruitLineRoot"
        attachment.Parent = root
        record.RootAttachment = attachment
    end
    if not record.FruitAttachment or record.FruitAttachment.Parent ~= record.Adornee then
        self.Context.Destroy(record.FruitAttachment)
        if record.Adornee and record.Adornee.Parent then
            local attachment = Instance.new("Attachment")
            attachment.Name = "DepHubFruitLineTarget"
            attachment.Parent = record.Adornee
            record.FruitAttachment = attachment
        end
    end
    if record.RootAttachment and record.FruitAttachment then
        record.Beam.Attachment0 = record.RootAttachment
        record.Beam.Attachment1 = record.FruitAttachment
    end
end

function Feature:_stopSpectate(record)
    if not record then return end
    record.Spectating = false
    if record.SpectateThread then pcall(task.cancel, record.SpectateThread); record.SpectateThread = nil end
    local camera = workspace.CurrentCamera
    if record.PreviousCamera and camera then
        pcall(function()
            camera.CameraType = record.PreviousCamera.Type
            camera.CameraSubject = record.PreviousCamera.Subject
            if record.PreviousCamera.Type == Enum.CameraType.Scriptable then camera.CFrame = record.PreviousCamera.CFrame end
        end)
    end
    record.PreviousCamera = nil
end

function Feature:_startSpectate(record)
    if not record or record.Spectating or self.State.Destroyed then return end
    local camera = workspace.CurrentCamera
    if not camera or not record.Instance or not record.Instance.Parent then return end
    local adornee = self:_adornee(record.Instance)
    local position = self:_position(record.Instance, adornee)
    if not position then return end
    record.Spectating = true
    record.PreviousCamera = {Type = camera.CameraType, Subject = camera.CameraSubject, CFrame = camera.CFrame}
    task.defer(function()
        if not record.Spectating or not self.Enabled or self.State.Destroyed then return end
        local ok = pcall(function() self.Context.LocalPlayer:RequestStreamAroundAsync(position) end)
        if not ok then return end
        if not record.Spectating or not self.Enabled or self.State.Destroyed then return end
        camera.CameraType = Enum.CameraType.Scriptable
        record.SpectateThread = task.spawn(function()
            while record.Spectating and self.Enabled and not self.State.Destroyed do
                local currentAdornee = self:_adornee(record.Instance)
                local currentPosition = self:_position(record.Instance, currentAdornee)
                if not currentPosition then break end
                local target = currentPosition + Vector3.new(0, 2.5, 0)
                camera.CFrame = CFrame.lookAt(target + Vector3.new(0, 5, 12), target)
                task.wait()
            end
            if record.Spectating then self:_stopSpectate(record) end
        end)
    end)
end

function Feature:_update(record)
    if self.State.Destroyed or not record.Label or not record.Label.Parent then return end
    local adornee = self:_adornee(record.Instance)
    local position = self:_position(record.Instance, adornee)
    local root = self.Context.GetRoot(self.Context.LocalPlayer.Character)
    if not position or not root then return end
    local distance = (root.Position - position).Magnitude
    local fruitName = self:_fruitName(record.Instance, adornee)
    local droppedBy = self:_droppedBy(record.Instance) or "Desconhecido"
    local island = self:_islandName(record.Instance, position)
    record.Adornee = adornee
    record.Label.Text = fruitName .. " - Dropado por: " .. droppedBy .. "\nIlha: " .. island .. "\nDistância: " .. tostring(math_floor(distance + 0.5)) .. " studs"
    record.Billboard.Adornee = adornee
    self:_lineFor(record, position)
end

function Feature:_remove(instance)
    local record = self.Records[instance]
    if not record then return end
    self.Records[instance] = nil
    self:_stopSpectate(record)
    self.Context.DisconnectAll(record.Connections)
    self.Context.Destroy(record.Billboard)
    self.Context.Destroy(record.Beam)
    self.Context.Destroy(record.FruitAttachment)
    self.Context.Destroy(record.RootAttachment)
end

function Feature:_passesRarityFilter(instance, adornee)
    local filter = self.State and self.State.FruitRarityFilter
    if type(filter) ~= "table" or filter.Enabled ~= true then return true end
    local quests = self.State and self.State.QuestData
    if not quests or type(quests.RarityOf) ~= "function" then return true end
    local name = self:_fruitName(instance, adornee)
    local rarity = quests.RarityOf(name)
    if not rarity then return true end
    return filter[rarity] == true
end

function Feature:_create(instance)
    if self.State.Destroyed or not self.Enabled or self.Records[instance] or not self:_isFruit(instance) then return end
    local adornee = self:_adornee(instance)
    if not adornee then return end
    if not self:_passesRarityFilter(instance, adornee) then return end
    local billboard = Instance.new("BillboardGui")
    billboard.Name = "DepHubFruitESP"
    billboard.Adornee = adornee
    billboard.AlwaysOnTop = true
    billboard.MaxDistance = 10000
    billboard.Size = UDim2.fromOffset(300, 70)
    billboard.StudsOffset = Vector3.new(0, 2.8, 0)
    billboard.Parent = adornee
    local label = Instance.new("TextLabel")
    label.BackgroundTransparency = 1
    label.Size = UDim2.new(1, 0, 0, 70)
    label.Font = Enum.Font.GothamBold
    label.TextSize = 13
    label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    label.TextStrokeTransparency = 0
    label.TextColor3 = Color3.fromRGB(255, 235, 90)
    label.TextWrapped = true
    label.Parent = billboard
    local beam = Instance.new("Beam")
    beam.Name = "DepHubFruitESPLine"
    beam.FaceCamera = true
    beam.Width0 = 0.055
    beam.Width1 = 0.055
    beam.LightEmission = 1
    beam.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255))
    beam.Transparency = NumberSequence.new(0.12)
    beam.Parent = self.Context.Workspace
    local record = {Instance = instance, Billboard = billboard, Label = label, Beam = beam, Adornee = adornee, FruitAttachment = nil, RootAttachment = nil, Spectating = false, SpectateThread = nil, PreviousCamera = nil, Connections = {}}
    self.Records[instance] = record
    self:_update(record)
    self.Context.Connect(record.Connections, instance.AncestryChanged, function(_, parent)
        if not parent or not self:_isFruit(instance) then self:_remove(instance) end
    end)
    if instance:IsA("Tool") then
        self.Context.Connect(record.Connections, instance.ChildAdded, function(child)
            if child.Name == "Fruit" then task.defer(function() if self.Records[instance] then self:_update(record) end end) end
        end)
        self.Context.Connect(record.Connections, instance.ChildRemoved, function(child)
            if child.Name == "Fruit" then task.defer(function() if self.Records[instance] and not self:_isDroppedTool(instance) then self:_remove(instance) end end) end
        end)
        self.Context.Connect(record.Connections, instance:GetPropertyChangedSignal("Name"), function() self:_update(record) end)
    end
end

function Feature:_scanRoot(root)
    if not root then return end
    for _, instance in ipairs(root:GetDescendants()) do if self:_isFruit(instance) then self:_create(instance) end end
end

function Feature:Enable()
    if self.Enabled or self.State.Destroyed then return true end
    self.Enabled = true
    self:_scanRoot(self.Context.Workspace)
    local worldOrigin = self.Context.Workspace:FindFirstChild("_WorldOrigin")
    local fruitSpawns = worldOrigin and worldOrigin:FindFirstChild("FruitSpawns")
    if fruitSpawns then self:_scanRoot(fruitSpawns) end
    self.Context.Connect(self.Connections, self.Context.Workspace.DescendantAdded, function(instance)
        if self.Enabled and self:_isFruit(instance) then task.defer(function() self:_create(instance) end) end
    end)
    self.Context.Connect(self.Connections, self.Context.Workspace.DescendantRemoving, function(instance) self:_remove(instance) end)
    self.Thread = task.spawn(function()
        while self.Enabled and not self.State.Destroyed do
            for instance, record in pairs(self.Records) do
                if not self:_isFruit(instance) or not record.Label or not record.Label.Parent then self:_remove(instance) else self:_update(record) end
            end
            for instance, record in pairs(self.Records) do
                if not self:_passesRarityFilter(instance, record.Adornee) then self:_remove(instance) end
            end
            jitter(0.2)
        end
    end)
    return true
end

function Feature:Disable()
    if not self.Enabled then return true end
    self.Enabled = false
    self.Context.DisconnectAll(self.Connections)
    if self.Thread then pcall(task.cancel, self.Thread); self.Thread = nil end
    for instance in pairs(self.Records) do self:_remove(instance) end
    return true
end

function Feature:IsEnabled() return self.Enabled end
function Feature:Destroy()
    if not self.Context then return end
    self:Disable()
    self.Context = nil
    self.State = nil
    self.Records = nil
end

return Feature

]],
    ["src/games/features/bloxfruits/fruitvfx.lua"] = [[
-- Local, on-demand cosmetic edits. No polling, remote calls or anti-cheat hooks.
local Feature = {}
Feature.__index = Feature

local rawPalettes = {
    Red = {{255,0,0},{255,70,70},{200,0,0},{255,140,140},{150,0,0},{255,40,40},{220,20,20}},
    Orange = {{255,90,0},{255,140,40},{220,70,0},{255,190,100},{170,50,0},{255,110,20},{230,80,10}},
    Yellow = {{255,220,0},{255,240,80},{220,180,0},{255,250,150},{170,140,0},{255,210,40},{230,190,20}},
    Green = {{0,255,80},{70,255,130},{0,200,60},{140,255,175},{0,150,45},{40,255,100},{20,220,80}},
    Cyan = {{0,230,255},{80,245,255},{0,185,220},{140,250,255},{0,140,180},{30,220,255},{20,200,230}},
    Blue = {{0,100,255},{80,150,255},{0,70,210},{140,190,255},{0,50,160},{40,120,255},{20,90,220}},
    Purple = {{140,0,255},{185,80,255},{100,0,210},{215,140,255},{80,0,160},{160,40,255},{125,20,220}},
    Pink = {{255,0,170},{255,80,195},{210,0,135},{255,140,215},{160,0,105},{255,40,180},{220,20,150}},
    White = {{255,255,255},{235,235,255},{210,210,230},{255,255,255},{180,180,200},{245,245,255},{220,220,240}},
    Black = {{25,25,25},{50,50,50},{10,10,10},{80,80,80},{5,5,5},{35,35,35},{15,15,15}}
}
local palettes = {}
for name, values in pairs(rawPalettes) do
    palettes[name] = {}
    for index, rgb in ipairs(values) do palettes[name][index] = Color3.fromRGB(rgb[1], rgb[2], rgb[3]) end
end
local presetOrder = {"Red", "Orange", "Yellow", "Green", "Cyan", "Blue", "Purple", "Pink", "White", "Black"}
local labels = {Red="Vermelho", Orange="Laranja", Yellow="Amarelo", Green="Verde", Cyan="Ciano", Blue="Azul", Purple="Roxo", Pink="Rosa", White="Branco", Black="Preto"}
local ids = {}
for id, name in pairs(labels) do ids[name] = id end

-- Register additional fruits with their own folders, palette list and slot rules.
local fruits = {
    Rumble = {
        Folder = "LightningFruitVFXColor",
        Palettes = palettes,
        PresetOrder = presetOrder,
        Forms = {
            Default = {Prefix = "Default_Color", ExistingOnly = true},
            Shifted = {Prefix = "Shifted_Color", Slots = 7}
        }
    }
}
local ORIGINAL = "Original (cor/skin anterior)"
local formIds = {["Normal (Default)"]="Default", ["Transformada (Shifted)"]="Shifted", Ambas="Both"}

local function empty(value) return next(value) == nil end

function Feature.new(context)
    return setmetatable({Player = context.LocalPlayer, Records = {}, Destroyed = false, Busy = false}, Feature)
end

function Feature:GetFruits()
    local names = {}
    for name in pairs(fruits) do names[#names + 1] = name end
    table.sort(names)
    return names
end

function Feature:GetColors(fruit)
    local definition = fruits[fruit]
    if not definition then return {} end
    local names = {ORIGINAL}
    for _, id in ipairs(definition.PresetOrder) do names[#names + 1] = labels[id] or id end
    return names
end

function Feature:_prune()
    for object, record in pairs(self.Records) do
        if not object:IsDescendantOf(self.Player) or empty(record.Owned) then self.Records[object] = nil end
    end
end

function Feature:_resolve(fruit, form)
    local definition = fruits[fruit]
    if not definition then return nil, "Fruta não cadastrada." end
    local forms = form == "Both" and {"Default", "Shifted"} or {form}
    local root = self.Player and self.Player:FindFirstChild(definition.Folder)
    if not root then return nil, "Dados da Rumble ausentes. Equipe/carregue a fruta e tente novamente." end
    local targets = {}
    for _, name in ipairs(forms) do
        local rule = definition.Forms[name]
        if not rule then return nil, "Forma inválida." end
        local object = root:FindFirstChild(name)
        if not object then return nil, "Pasta " .. name .. " ausente. Selecione apenas a forma disponível." end
        local ok, attributes = pcall(object.GetAttributes, object)
        if not ok then return nil, "Não foi possível ler os atributos de " .. name .. "." end
        targets[#targets + 1] = {Object = object, Attributes = attributes, Rule = rule, Form = name}
    end
    return targets
end

-- Before/after journaling makes both applying and restoring reversible on failure.
function Feature:_commit(changes)
    local completed = {}
    for _, change in ipairs(changes) do
        local ok = pcall(function()
            if change.Object:GetAttribute(change.Key) ~= change.Before then error("Attribute changed externally") end
            change.Object:SetAttribute(change.Key, change.After)
        end)
        if not ok then
            local rolledBack = true
            for index = #completed, 1, -1 do
                local previous = completed[index]
                local restored = pcall(function()
                    if previous.Object:GetAttribute(previous.Key) ~= previous.After then error("Attribute changed externally") end
                    previous.Object:SetAttribute(previous.Key, previous.Before)
                end)
                if restored then previous.Record.Owned[previous.Key] = previous.PreviousOwned else rolledBack = false end
            end
            return false, rolledBack and "Não foi possível aplicar. As alterações desta tentativa foram desfeitas." or "Falha parcial. Use Restaurar antes de tentar novamente."
        end
        change.PreviousOwned = change.Record.Owned[change.Key]
        if change.Restore then change.Record.Owned[change.Key] = nil else change.Record.Owned[change.Key] = change.After end
        completed[#completed + 1] = change
    end
    return true, #completed
end

function Feature:Apply(fruit, color, form)
    if self.Destroyed then return false, "Módulo encerrado." end
    if self.Busy then return false, "Aguarde a operação atual." end
    form = formIds[form] or form or "Default"
    if color == ORIGINAL or color == "Original" then return self:Restore(fruit, form) end
    local definition = fruits[fruit]
    local palette = definition and definition.Palettes[ids[color] or color]
    if not palette then return false, "Cor ou fruta não cadastrada." end
    self:_prune()
    local targets, reason = self:_resolve(fruit, form)
    if not targets then return false, reason end
    local changes = {}
    for _, target in ipairs(targets) do
        local object, attributes, rule = target.Object, target.Attributes, target.Rule
        local record = self.Records[object] or {Original = table.clone(attributes), Owned = {}, Fruit = fruit, Form = target.Form}
        for key, applied in pairs(record.Owned) do
            if attributes[key] ~= applied then return false, "As cores mudaram fora do módulo. Use Restaurar para liberar o estado anterior e tente novamente." end
        end
        local slots = {}
        if rule.ExistingOnly then
            for key, value in pairs(attributes) do
                local index = tonumber(key:match("^" .. rule.Prefix .. "(%d+)$"))
                if index then
                    if not palette[index] or typeof(value) ~= "Color3" then return false, "Formato de cores do Default incompatível; nenhum atributo foi alterado." end
                    slots[#slots + 1] = index
                end
            end
            table.sort(slots)
            if #slots == 0 then return false, "Nenhuma cor original encontrada em Default; não vou inventar valores." end
        else
            for index = 1, rule.Slots do slots[#slots + 1] = index end
        end
        for _, index in ipairs(slots) do
            local key = rule.Prefix .. index
            local current = attributes[key]
            if current ~= nil and typeof(current) ~= "Color3" then return false, "Atributo de cor com tipo incompatível: " .. key end
            if current ~= palette[index] then
                changes[#changes + 1] = {Object = object, Key = key, Before = current, After = palette[index], Record = record}
            end
        end
    end
    self.Busy = true
    for _, change in ipairs(changes) do self.Records[change.Object] = change.Record end
    local ok, result = self:_commit(changes)
    self.Busy = false
    self:_prune()
    if not ok then return false, result end
    return true, result == 0 and "Essa paleta já está aplicada." or "Paleta aplicada localmente. A aparência anterior foi preservada."
end

function Feature:Restore(fruit, form)
    if self.Busy then return false, "Aguarde a operação atual." end
    form = formIds[form] or form or "Both"
    if fruit and not fruits[fruit] then return false, "Fruta não cadastrada." end
    if form ~= "Both" and form ~= "Default" and form ~= "Shifted" then return false, "Forma inválida." end
    self:_prune()
    local changes, released, skipped = {}, {}, 0
    for object, record in pairs(self.Records) do
        if (not fruit or record.Fruit == fruit) and (form == "Both" or record.Form == form) then
            local ok, attributes = pcall(object.GetAttributes, object)
            if not ok then return false, "Não foi possível ler o estado para restaurar. Tente novamente." end
            for key, applied in pairs(record.Owned) do
                local original, current = record.Original[key], attributes[key]
                if current == applied and current ~= original then
                    changes[#changes + 1] = {Object = object, Key = key, Before = current, After = original, Record = record, Restore = true}
                else
                    -- Preserve updates made by the game/another script instead of fighting them.
                    released[#released + 1] = {Record = record, Key = key}
                    if current ~= original then skipped += 1 end
                end
            end
        end
    end
    self.Busy = true
    local ok, result = self:_commit(changes)
    self.Busy = false
    if not ok then return false, result end
    for _, item in ipairs(released) do item.Record.Owned[item.Key] = nil end
    self:_prune()
    if skipped > 0 then return true, "Restaurado o que ainda pertencia ao módulo; cores alteradas pelo jogo foram preservadas.", "Warning" end
    return true, result == 0 and "Nenhuma alteração local pendente para restaurar." or "Cor/skin anterior restaurada; atributos criados pelo módulo foram removidos."
end

function Feature:Destroy()
    if self.Destroyed then return end
    local ok, reason = self:Restore(nil, "Both")
    if not ok then return false, reason end
    self.Destroyed = true
    self.Records = {}
    return true
end

return Feature

]],
    ["src/games/features/bloxfruits/observation.lua"] = [[
local Feature = {}
Feature.__index = Feature

-- Humanised timing: vary each periodic wait to avoid a perfectly periodic loop.
local function jitter(base, spread)
    spread = spread or 0.15
    return task.wait(base * (1 + (math.random() * 2 - 1) * spread))
end

function Feature.new(context)
    return setmetatable({Context = context, State = context.State, Enabled = false, Thread = nil}, Feature)
end

function Feature:_setVisionRadius(value)
    local player = self.Context.LocalPlayer
    if not player then return false end
    local ok = pcall(function()
        if player.VisionRadius ~= value then player.VisionRadius = value end
    end)
    if ok and player.VisionRadius == value then return true end
    local valueObject = player:FindFirstChild("VisionRadius")
    if valueObject and valueObject:IsA("NumberValue") and valueObject.Value ~= value then pcall(function() valueObject.Value = value end) end
    return valueObject and valueObject:IsA("NumberValue") and valueObject.Value == value or false
end

function Feature:Enable()
    if self.Enabled or self.State.Destroyed then return true end
    self.Enabled = true
    self.Thread = task.spawn(function()
        while self.Enabled and not self.State.Destroyed do
            pcall(function()
                if self.Context.LocalPlayer.VisionRadius ~= 5000 then self:_setVisionRadius(5000) end
            end)
            jitter(0.5)
        end
    end)
    return true
end

function Feature:Disable()
    self.Enabled = false
    if self.Thread then pcall(task.cancel, self.Thread); self.Thread = nil end
    return true
end

function Feature:IsEnabled() return self.Enabled end
function Feature:Destroy()
    if not self.Context then return end
    self:Disable()
    self.Context = nil
    self.State = nil
end

return Feature

]],
    ["src/games/features/bloxfruits/playeresp.lua"] = [[
local Feature = {}
Feature.__index = Feature

local function colorToHex(color)
    local r = math.floor(color.R * 255 + 0.5)
    local g = math.floor(color.G * 255 + 0.5)
    local b = math.floor(color.B * 255 + 0.5)
    return string.format("#%02X%02X%02X", r, g, b)
end

function Feature.new(context)
    local self = setmetatable({}, Feature)
    self.Context = context
    self.State = context.State
    self.Connections = {}
    self.Records = {}
    self.Enabled = false
    return self
end

function Feature:_updateText(record)
    if not record.Label or not record.Label.Parent then return end
    local nameColor = colorToHex(self.Context.TeamColor(record.Player))
    local lines = {
        string.format('<font color="%s">%s</font>', nameColor, record.Player.Name),
        string.format('<font color="#FFFFFF">%s</font>', self.Context.HealthText(record.Humanoid))
    }
    if not record.Protected then
        lines[#lines + 1] = string.format('<font color="%s">PvP: Ativado</font>', nameColor)
    end
    record.Label.Text = table.concat(lines, "\n")
end

function Feature:_updateProtection(record)
    if self.State.Destroyed or not record.Character or not record.Character.Parent then return end
    record.Protected = self.Context.HasProtection(record.Character)
    self:_updateText(record)
end

function Feature:_updateAppearance(record)
    if self.State.Destroyed or not record.Highlight or not record.Label then return end
    local color = self.Context.TeamColor(record.Player)
    record.Highlight.FillColor = color
    record.Highlight.OutlineColor = color
    record.Label.TextColor3 = Color3.fromRGB(255, 255, 255)
    self:_updateText(record)
end

function Feature:_remove(character)
    local record = self.Records[character]
    if not record then return end
    self.Records[character] = nil
    self.Context.DisconnectAll(record.Connections)
    self.Context.Destroy(record.Highlight)
    self.Context.Destroy(record.Billboard)
end

function Feature:_create(character)
    if self.State.Destroyed or not self.Enabled or not character then return end
    if character == self.Context.LocalPlayer.Character or self.Records[character] then return end
    local player = self.Context.GetPlayer(character)
    if not player or player == self.Context.LocalPlayer then return end
    local head = character:FindFirstChild("Head")
    local humanoid = self.Context.GetHumanoid(character)
    if not head or not humanoid then return end

    local highlight = Instance.new("Highlight")
    highlight.Name = "DepHubPlayerESP"
    highlight.Adornee = character
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.FillTransparency = 0
    highlight.OutlineTransparency = 0
    local color = self.Context.TeamColor(player)
    highlight.FillColor = color
    highlight.OutlineColor = color
    highlight.Parent = character

    local billboard = Instance.new("BillboardGui")
    billboard.Name = "DepHubPlayerESPText"
    billboard.Adornee = head
    billboard.AlwaysOnTop = true
    billboard.MaxDistance = 10000
    billboard.Size = UDim2.fromOffset(250, 76)
    billboard.StudsOffset = Vector3.new(0, 3.25, 0)
    billboard.Parent = head

    local label = Instance.new("TextLabel")
    label.BackgroundTransparency = 1
    label.Size = UDim2.fromScale(1, 1)
    label.Font = Enum.Font.GothamBold
    label.TextSize = 14
    label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    label.TextStrokeTransparency = 0
    label.RichText = true
    label.TextColor3 = Color3.fromRGB(255, 255, 255)
    label.Parent = billboard

    local record = {Character = character, Player = player, Humanoid = humanoid, Highlight = highlight, Billboard = billboard, Label = label, Protected = self.Context.HasProtection(character), Connections = {}}
    self.Records[character] = record
    self:_updateAppearance(record)

    self.Context.Connect(record.Connections, humanoid:GetPropertyChangedSignal("Health"), function() self:_updateText(record) end)
    self.Context.Connect(record.Connections, humanoid:GetPropertyChangedSignal("MaxHealth"), function() self:_updateText(record) end)
    self.Context.Connect(record.Connections, player:GetPropertyChangedSignal("Team"), function() self:_updateAppearance(record) end)
    self.Context.Connect(record.Connections, character.ChildAdded, function(child)
        if child:IsA("ForceField") or self.Context.IsProtectionName(child.Name) then self:_updateProtection(record) end
    end)
    self.Context.Connect(record.Connections, character.ChildRemoved, function(child)
        if child:IsA("ForceField") or self.Context.IsProtectionName(child.Name) then task.defer(function() self:_updateProtection(record) end) end
    end)
    self.Context.Connect(record.Connections, character.DescendantAdded, function(descendant)
        if self.Context.IsProtectionName(descendant.Name) or descendant:IsA("ForceField") then self:_updateProtection(record) end
    end)
    self.Context.Connect(record.Connections, character.DescendantRemoving, function(descendant)
        if self.Context.IsProtectionName(descendant.Name) or descendant:IsA("ForceField") then task.defer(function() self:_updateProtection(record) end) end
    end)
    for _, attributeName in ipairs({"PvPDisabled", "PVPDisabled", "PvPProtection", "Protection", "Protected", "SafeZone", "NoPvP"}) do
        self.Context.Connect(record.Connections, character:GetAttributeChangedSignal(attributeName), function() self:_updateProtection(record) end)
    end
    self.Context.Connect(record.Connections, character.AncestryChanged, function(_, parent)
        if not parent then self:_remove(character) end
    end)
end

function Feature:Enable()
    if self.Enabled or self.State.Destroyed then return true end
    local characters = self.Context.Workspace:FindFirstChild("Characters") or self.Context.Workspace:WaitForChild("Characters", 5)
    if not characters then return false end
    self.Enabled = true
    self.Characters = characters
    for _, character in ipairs(characters:GetChildren()) do
        if character:IsA("Model") then self:_create(character) end
    end
    self.Context.Connect(self.Connections, characters.ChildAdded, function(character)
        if self.Enabled and character:IsA("Model") then task.defer(function() self:_create(character) end) end
    end)
    self.Context.Connect(self.Connections, characters.ChildRemoved, function(character) self:_remove(character) end)
    return true
end

function Feature:Disable()
    if not self.Enabled then return true end
    self.Enabled = false
    self.Context.DisconnectAll(self.Connections)
    for character in pairs(self.Records) do self:_remove(character) end
    self.Characters = nil
    return true
end

function Feature:IsEnabled() return self.Enabled end
function Feature:Destroy()
    if not self.Context then return end
    self:Disable()
    self.Context = nil
    self.State = nil
    self.Records = nil
end

return Feature

]],
