    ["src/games/features/mm2/coinfarm.lua"] = [[
local game=game
local type=type
local pairs=pairs
local ipairs=ipairs
local os_clock=os.clock

local Factory={}

-- Humanised timing: vary each periodic wait to avoid a perfectly periodic loop.
local function jitter(base, spread)
    spread = spread or 0.15
    return task.wait(base * (1 + (math.random() * 2 - 1) * spread))
end

local function disconnectAll(list)
    for i=#list,1,-1 do
        local c=list[i]
        list[i]=nil
        if c then pcall(c.Disconnect,c) end
    end
end

function Factory.new(context)
    context=context or {}
    local Players=context.Players or game:GetService("Players")
    local Workspace=context.Workspace or game:GetService("Workspace")
    local LocalPlayer=context.LocalPlayer or Players.LocalPlayer
    local RoundTracker=context.RoundTracker
    local RoleTracker=context.RoleTracker

    local self={
        Enabled=false,
        Destroyed=false,
        Connections={},
        Containers=setmetatable({},{__mode="k"}),
        Coins=setmetatable({},{__mode="k"}),
        IgnoreUntil=setmetatable({},{__mode="k"}),
        Delay=tonumber(context.CoinDelay) or 0.05,
        SafeDistance=tonumber(context.CoinSafeDistance) or 18,
        Token=0,
        LastCoin=nil,
        DebugInfo={Runtime="idle",Containers=0,Coins=0,Teleports=0,Paused="none",LastCoin="none",LastTargetDistance=0,LastError="none"}
    }

    function self:_root()
        local character=LocalPlayer and LocalPlayer.Character
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        local root=character and character:FindFirstChild("HumanoidRootPart")
        if not humanoid or humanoid.Health<=0 or not root then return nil end
        return root
    end

    function self:_murderTooClose(root)
        if not RoleTracker then return false end
        local murder=RoleTracker:GetMurder()
        if not murder or murder==LocalPlayer then return false end
        local character=murder.Character
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        local murderRoot=character and character:FindFirstChild("HumanoidRootPart")
        if not murderRoot or not humanoid or humanoid.Health<=0 then return false end
        return (murderRoot.Position-root.Position).Magnitude<=self.SafeDistance
    end

    function self:_addCoin(object)
        if not object or not object.Parent or not object:IsA("BasePart") then return end
        local parent=object.Parent
        local insideContainer=false
        while parent and parent~=Workspace do
            if parent.Name=="CoinContainer" then insideContainer=true break end
            parent=parent.Parent
        end
        if insideContainer then self.Coins[object]=true end
    end

    function self:_registerContainer(container)
        if not container or self.Containers[container] then return end
        self.Containers[container]=true
        for _,object in ipairs(container:GetDescendants()) do self:_addCoin(object) end
    end

    function self:_initialScan()
        self.Containers=setmetatable({},{__mode="k"})
        self.Coins=setmetatable({},{__mode="k"})
        for _,object in ipairs(Workspace:GetDescendants()) do
            if object.Name=="CoinContainer" then self:_registerContainer(object) end
        end
    end

    function self:_refreshCounts()
        local containers=0
        for container in pairs(self.Containers) do
            if container and container.Parent then containers=containers+1 else self.Containers[container]=nil end
        end
        local coins=0
        for coin in pairs(self.Coins) do
            if coin and coin.Parent then coins=coins+1 else self.Coins[coin]=nil self.IgnoreUntil[coin]=nil end
        end
        self.DebugInfo.Containers=containers
        self.DebugInfo.Coins=coins
    end

    function self:_nearest(root)
        local now=os_clock()
        local best=nil
        local bestDistance=math.huge
        for coin in pairs(self.Coins) do
            if coin and coin.Parent then
                local ignored=self.IgnoreUntil[coin]
                if not ignored or now>=ignored then
                    local distance=(coin.Position-root.Position).Magnitude
                    if distance<bestDistance then
                        best=coin
                        bestDistance=distance
                    end
                end
            end
        end
        return best,bestDistance
    end

    function self:_teleportCoin(root,coin,distance)
        if not root or not root.Parent or not coin or not coin.Parent then return false end
        self.LastCoin=coin
        self.DebugInfo.LastCoin=coin:GetFullName()
        self.DebugInfo.LastTargetDistance=distance or 0
        self.IgnoreUntil[coin]=os_clock()+0.18
        local ok,err=pcall(function()
            root.CFrame=coin.CFrame*CFrame.new(0,1.8,0)
        end)
        if ok then
            self.DebugInfo.Teleports=self.DebugInfo.Teleports+1
            self.DebugInfo.LastError="none"
            return true
        end
        self.DebugInfo.LastError=tostring(err)
        return false
    end

    function self:_run(token)
        while self.Enabled and not self.Destroyed and token==self.Token do
            if RoundTracker and not RoundTracker:IsRoundActive() then
                self.DebugInfo.Paused="lobby"
                jitter(0.08)
            else
                local root=self:_root()
                if not root then
                    self.DebugInfo.Paused="dead"
                    jitter(0.08)
                elseif self:_murderTooClose(root) then
                    self.DebugInfo.Paused="murder nearby"
                    jitter(0.06)
                else
                    self:_refreshCounts()
                    local coin,distance=self:_nearest(root)
                    if not coin then
                        self.DebugInfo.Paused="no coins"
                        jitter(0.06)
                    else
                        self.DebugInfo.Paused="none"
                        self:_teleportCoin(root,coin,distance)
                        jitter(self.Delay)
                    end
                end
            end
        end
    end

    function self:SetSafeDistance(value)
        value=tonumber(value)
        if not value then return false end
        self.SafeDistance=math.max(0,math.min(80,value))
        return true
    end

    function self:SetDelay(value)
        value=tonumber(value)
        if not value then return false end
        self.Delay=math.max(0.02,math.min(0.3,value))
        return true
    end

    function self:GetDebugInfo()
        self:_refreshCounts()
        local out={}
        for k,v in pairs(self.DebugInfo) do out[k]=v end
        out.Delay=self.Delay
        out.SafeDistance=self.SafeDistance
        return out
    end

    function self:Enable()
        if self.Destroyed then return false end
        if self.Enabled then return true end
        self.Enabled=true
        self.DebugInfo.Runtime="running"
        self:_initialScan()
        self.Connections[#self.Connections+1]=Workspace.DescendantAdded:Connect(function(object)
            if object.Name=="CoinContainer" then self:_registerContainer(object) else self:_addCoin(object) end
        end)
        self.Connections[#self.Connections+1]=Workspace.DescendantRemoving:Connect(function(object)
            if self.Containers[object] then self.Containers[object]=nil end
            if self.Coins[object] then self.Coins[object]=nil self.IgnoreUntil[object]=nil end
        end)
        self.Token=self.Token+1
        local token=self.Token
        task.spawn(function()
            local ok,err=pcall(self._run,self,token)
            if not ok then self.DebugInfo.LastError=tostring(err) end
        end)
        return true
    end

    function self:Disable()
        if not self.Enabled then return true end
        self.Enabled=false
        self.Token=self.Token+1
        self.DebugInfo.Runtime="idle"
        disconnectAll(self.Connections)
        self.LastCoin=nil
        return true
    end

    function self:Destroy()
        if self.Destroyed then return end
        self:Disable()
        self.Destroyed=true
        self.DebugInfo.Runtime="destroyed"
        self.Containers={}
        self.Coins={}
        self.IgnoreUntil={}
    end

    return self
end

return Factory

]],
    ["src/games/features/mm2/esp.lua"] = [[
local game=game
local type=type
local pairs=pairs
local ipairs=ipairs

local Factory={}

function Factory.new(context)
    context=context or {}
    local Players=context.Players or game:GetService("Players")
    local RunService=context.RunService or game:GetService("RunService")
    local LocalPlayer=context.LocalPlayer or Players.LocalPlayer
    local RoleTracker=context.RoleTracker

    local self={Enabled=false,Destroyed=false,Connections={},Records={},Accumulator=0}

    local COLORS={
        Murder=Color3.fromRGB(255,72,72),
        Sheriff=Color3.fromRGB(70,160,255)
    }

    function self:_remove(player)
        local record=self.Records[player]
        self.Records[player]=nil
        if record then
            if record.Highlight then pcall(record.Highlight.Destroy,record.Highlight) end
            if record.Billboard then pcall(record.Billboard.Destroy,record.Billboard) end
        end
    end

    function self:_render(player,role)
        if player==LocalPlayer then
            self:_remove(player)
            return
        end
        if role~="Murder" and role~="Sheriff" then
            self:_remove(player)
            return
        end
        local character=player.Character
        local head=character and character:FindFirstChild("Head")
        if not character or not head then
            self:_remove(player)
            return
        end

        local record=self.Records[player]
        if record and record.Character~=character then
            self:_remove(player)
            record=nil
        end
        if not record then
            local highlight=Instance.new("Highlight")
            highlight.Name="DepHubMM2Highlight"
            highlight.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
            highlight.FillTransparency=0.42
            highlight.OutlineTransparency=1
            highlight.Adornee=character
            highlight.Parent=character

            local billboard=Instance.new("BillboardGui")
            billboard.Name="DepHubMM2Role"
            billboard.Size=UDim2.fromOffset(180,34)
            billboard.StudsOffset=Vector3.new(0,2.8,0)
            billboard.AlwaysOnTop=true
            billboard.Adornee=head
            billboard.Parent=head

            local text=Instance.new("TextLabel")
            text.Name="Text"
            text.Size=UDim2.fromScale(1,1)
            text.BackgroundTransparency=1
            text.Font=Enum.Font.GothamBold
            text.TextSize=13
            text.TextStrokeTransparency=0.25
            text.Parent=billboard

            record={Character=character,Highlight=highlight,Billboard=billboard,Text=text}
            self.Records[player]=record
        end

        local color=COLORS[role]
        record.Highlight.FillColor=color
        record.Text.Text=role:upper().." | "..player.Name
        record.Text.TextColor3=color
    end

    function self:Refresh()
        if self.Destroyed or not self.Enabled or not RoleTracker then return end
        for _,player in ipairs(Players:GetPlayers()) do
            self:_render(player,RoleTracker:GetRole(player))
        end
        for player in pairs(self.Records) do
            if not player.Parent then self:_remove(player) end
        end
    end

    function self:Enable()
        if self.Destroyed then return false end
        if self.Enabled then return true end
        self.Enabled=true
        self.Connections[#self.Connections+1]=RunService.Heartbeat:Connect(function(dt)
            self.Accumulator=self.Accumulator+dt
            if self.Accumulator>=0.2 then
                self.Accumulator=0
                self:Refresh()
            end
        end)
        self:Refresh()
        return true
    end

    function self:Disable()
        if not self.Enabled then return true end
        self.Enabled=false
        for i=#self.Connections,1,-1 do
            local c=self.Connections[i]
            self.Connections[i]=nil
            if c then pcall(c.Disconnect,c) end
        end
        for player in pairs(self.Records) do self:_remove(player) end
        return true
    end

    function self:Destroy()
        if self.Destroyed then return end
        self:Disable()
        self.Destroyed=true
    end

    return self
end

return Factory

]],
    ["src/games/features/mm2/gundrop.lua"] = [[
local game=game
local type=type
local os_clock=os.clock

local Factory={}

local function disconnectAll(list)
    for i=#list,1,-1 do
        local c=list[i]
        list[i]=nil
        if c then pcall(c.Disconnect,c) end
    end
end

function Factory.new(context)
    context=context or {}
    local Players=context.Players or game:GetService("Players")
    local RunService=context.RunService or game:GetService("RunService")
    local LocalPlayer=context.LocalPlayer or Players.LocalPlayer
    local RoleTracker=context.RoleTracker
    local RoundTracker=context.RoundTracker

    local self={
        Destroyed=false,
        ESPEnabled=false,
        AutoPickup=false,
        Connections={},
        Highlight=nil,
        Billboard=nil,
        CurrentDrop=nil,
        SafeDistance=tonumber(context.GunSafeDistance) or 22,
        PickupHold=tonumber(context.GunPickupHold) or 0.16,
        Cooldown=0.8,
        LastAttempt=0,
        Busy=false,
        Token=0,
        DebugInfo={GunDrop="missing",MurderDistance=-1,Safe=true,Attempts=0,Pickups=0,Returns=0,LastAction="idle",LastError="none"}
    }

    function self:_localRoot()
        local character=LocalPlayer and LocalPlayer.Character
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        local root=character and character:FindFirstChild("HumanoidRootPart")
        if not humanoid or humanoid.Health<=0 or not root then return nil end
        return root
    end

    function self:_part(drop)
        if not drop or not drop.Parent then return nil end
        if drop:IsA("BasePart") then return drop end
        return drop:FindFirstChildWhichIsA("BasePart",true)
    end

    function self:_hasLocalGun()
        if not RoleTracker then return false end
        if type(RoleTracker.HasTool)=="function" then return RoleTracker:HasTool(LocalPlayer,"Gun") end
        local character=LocalPlayer and LocalPlayer.Character
        local backpack=LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
        return (character and character:FindFirstChild("Gun",true)~=nil) or (backpack and backpack:FindFirstChild("Gun",true)~=nil)
    end

    function self:_murderDistance(dropPart)
        local murder=RoleTracker and RoleTracker:GetMurder() or nil
        if not murder or murder==LocalPlayer then return math.huge end
        local character=murder.Character
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        local root=character and character:FindFirstChild("HumanoidRootPart")
        if not root or not humanoid or humanoid.Health<=0 then return math.huge end
        return (root.Position-dropPart.Position).Magnitude
    end

    function self:_destroyESP()
        if self.Highlight then pcall(self.Highlight.Destroy,self.Highlight) self.Highlight=nil end
        if self.Billboard then pcall(self.Billboard.Destroy,self.Billboard) self.Billboard=nil end
    end

    function self:_updateESP(drop)
        if not self.ESPEnabled or not drop or not drop.Parent then
            self:_destroyESP()
            return
        end
        if self.CurrentDrop==drop and self.Highlight and self.Highlight.Parent and self.Billboard and self.Billboard.Parent then return end
        self:_destroyESP()
        local part=self:_part(drop)
        if not part then return end

        local highlight=Instance.new("Highlight")
        highlight.Name="DepHubMM2GunDrop"
        highlight.Adornee=drop
        highlight.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
        highlight.FillColor=Color3.fromRGB(80,170,255)
        highlight.FillTransparency=.25
        highlight.OutlineColor=Color3.fromRGB(255,255,255)
        highlight.OutlineTransparency=.15
        highlight.Parent=drop
        self.Highlight=highlight

        local billboard=Instance.new("BillboardGui")
        billboard.Name="DepHubMM2GunDropLabel"
        billboard.Adornee=part
        billboard.AlwaysOnTop=true
        billboard.Size=UDim2.fromOffset(110,26)
        billboard.StudsOffset=Vector3.new(0,2.2,0)
        billboard.Parent=part
        local label=Instance.new("TextLabel")
        label.Size=UDim2.fromScale(1,1)
        label.BackgroundTransparency=1
        label.Text="GUN DROP"
        label.TextColor3=Color3.fromRGB(255,255,255)
        label.TextSize=11
        label.Font=Enum.Font.GothamBold
        label.TextStrokeTransparency=.45
        label.Parent=billboard
        self.Billboard=billboard
    end

    function self:_getDrop()
        local drop=RoleTracker and type(RoleTracker.GetGunDrop)=="function" and RoleTracker:GetGunDrop() or nil
        if drop and drop.Parent then
            self.CurrentDrop=drop
            self.DebugInfo.GunDrop=drop:GetFullName()
            return drop
        end
        self.CurrentDrop=nil
        self.DebugInfo.GunDrop="missing"
        return nil
    end

    function self:_tryPickup()
        if self.Destroyed or not self.AutoPickup or self.Busy then return end
        if os_clock()-self.LastAttempt<self.Cooldown then return end
        if RoundTracker and not RoundTracker:IsRoundActive() then
            self.DebugInfo.LastAction="waiting round"
            return
        end
        if RoleTracker and RoleTracker:GetMurder()==LocalPlayer then
            self.DebugInfo.LastAction="local murder"
            return
        end
        if self:_hasLocalGun() then
            self.DebugInfo.LastAction="already has gun"
            return
        end

        local drop=self:_getDrop()
        local part=self:_part(drop)
        local root=self:_localRoot()
        if not part or not root then return end

        local murderDistance=self:_murderDistance(part)
        self.DebugInfo.MurderDistance=murderDistance==math.huge and -1 or murderDistance
        self.DebugInfo.Safe=murderDistance>self.SafeDistance
        if murderDistance<=self.SafeDistance then
            self.DebugInfo.LastAction="murder near gun"
            return
        end

        self.LastAttempt=os_clock()
        self.Busy=true
        self.DebugInfo.Attempts=self.DebugInfo.Attempts+1
        self.DebugInfo.LastAction="picking gun"
        local token=self.Token
        local origin=root.CFrame

        task.spawn(function()
            local ok,err=pcall(function()
                if self.Destroyed or not self.AutoPickup or token~=self.Token or not part.Parent or not root.Parent then return end
                root.CFrame=part.CFrame*CFrame.new(0,1.4,0)
                if type(firetouchinterest)=="function" then
                    pcall(firetouchinterest,root,part,0)
                    task.wait(0.03)
                    pcall(firetouchinterest,root,part,1)
                end
                task.wait(self.PickupHold)
                if self:_hasLocalGun() or not drop.Parent then
                    self.DebugInfo.Pickups=self.DebugInfo.Pickups+1
                    self.DebugInfo.LastAction="gun collected"
                else
                    self.DebugInfo.LastAction="pickup retry"
                end
            end)
            if not ok then self.DebugInfo.LastError=tostring(err) end
            if root and root.Parent then
                pcall(function() root.CFrame=origin end)
                self.DebugInfo.Returns=self.DebugInfo.Returns+1
            end
            self.Busy=false
        end)
    end

    function self:SetESP(value)
        if self.Destroyed then return false end
        self.ESPEnabled=value==true
        if not self.ESPEnabled then self:_destroyESP() else self:_updateESP(self:_getDrop()) end
        return true
    end

    function self:SetAutoPickup(value)
        if self.Destroyed then return false end
        self.AutoPickup=value==true
        self.Token=self.Token+1
        if not self.AutoPickup then self.Busy=false end
        return true
    end

    function self:SetSafeDistance(value)
        value=tonumber(value)
        if not value then return false end
        self.SafeDistance=math.max(5,math.min(80,value))
        return true
    end

    function self:SetPickupHold(value)
        value=tonumber(value)
        if not value then return false end
        self.PickupHold=math.max(0.05,math.min(0.5,value))
        return true
    end

    function self:GetDebugInfo()
        local out={}
        for k,v in pairs(self.DebugInfo) do out[k]=v end
        out.SafeDistance=self.SafeDistance
        out.PickupHold=self.PickupHold
        out.Busy=self.Busy
        return out
    end

    self.Connections[#self.Connections+1]=RunService.Heartbeat:Connect(function()
        if self.Destroyed then return end
        local drop=self:_getDrop()
        self:_updateESP(drop)
        if self.AutoPickup then self:_tryPickup() end
    end)

    function self:Destroy()
        if self.Destroyed then return end
        self.Destroyed=true
        self.Token=self.Token+1
        self.AutoPickup=false
        self.ESPEnabled=false
        disconnectAll(self.Connections)
        self:_destroyESP()
        self.CurrentDrop=nil
    end

    return self
end

return Factory

]],
    ["src/games/features/mm2/playerteleport.lua"] = [[
local game=game
local type=type
local ipairs=ipairs

local Factory={}

function Factory.new(context)
    context=context or {}
    local Players=context.Players or game:GetService("Players")
    local LocalPlayer=context.LocalPlayer or Players.LocalPlayer
    local RoundTracker=context.RoundTracker

    local self={
        Destroyed=false,
        Index=0,
        LastTarget=nil,
        DebugInfo={Teleports=0,LastTarget="none",AliveTargets=0,LastError="none"}
    }

    function self:_root(player)
        local character=player and player.Character
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        local root=character and character:FindFirstChild("HumanoidRootPart")
        if not humanoid or humanoid.Health<=0 or not root then return nil end
        return root
    end

    function self:GetAliveTargets()
        local targets={}
        if RoundTracker and type(RoundTracker.GetAliveRoundPlayers)=="function" then
            targets=RoundTracker:GetAliveRoundPlayers()
        else
            for _,player in ipairs(Players:GetPlayers()) do
                if player~=LocalPlayer and self:_root(player) then targets[#targets+1]=player end
            end
            table.sort(targets,function(a,b) return string.lower(a.Name)<string.lower(b.Name) end)
        end
        self.DebugInfo.AliveTargets=#targets
        return targets
    end

    function self:TeleportNext()
        if self.Destroyed then return false,"destroyed" end
        local localRoot=self:_root(LocalPlayer)
        if not localRoot then return false,"local player unavailable" end

        local targets=self:GetAliveTargets()
        if #targets==0 then
            self.Index=0
            self.LastTarget=nil
            self.DebugInfo.LastTarget="none"
            return false,"NO ALIVE PLAYERS"
        end

        self.Index=self.Index+1
        if self.Index>#targets then self.Index=1 end
        local target=targets[self.Index]
        local targetRoot=self:_root(target)
        if not targetRoot then
            return false,"TARGET LOST"
        end

        local ok,err=pcall(function()
            localRoot.CFrame=targetRoot.CFrame*CFrame.new(0,0,4)
        end)
        if not ok then
            self.DebugInfo.LastError=tostring(err)
            return false,"TELEPORT FAILED"
        end

        self.LastTarget=target
        self.DebugInfo.Teleports=self.DebugInfo.Teleports+1
        self.DebugInfo.LastTarget=target.Name
        self.DebugInfo.LastError="none"
        return true,target.Name
    end

    function self:GetDebugInfo()
        local out={}
        for k,v in pairs(self.DebugInfo) do out[k]=v end
        return out
    end

    function self:Destroy()
        self.Destroyed=true
        self.LastTarget=nil
    end

    return self
end

return Factory

