    ["src/games/features/restauranttycoon3/autofarm-friends.lua"] = [[
local Players = game:GetService("Players")
local localPlayer = Players.LocalPlayer

-- Humanised timing: vary periodic waits so the automation loop is not perfectly periodic.
local function jitter(base, spread)
    spread = spread or 0.15
    return task.wait(base * (1 + (math.random() * 2 - 1) * spread))
end

local AutoFarmFriendsModule = {}
AutoFarmFriendsModule.Enabled = false

local activeInteractions = {}
local farmThread = nil

local friendList = {}
local lastFriendUpdate = 0

local function updateFriendsList()
    local currentTime = tick()
    if currentTime - lastFriendUpdate < 30 then return end

    table.clear(friendList)
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= localPlayer then
            pcall(function()
                if localPlayer:IsFriendsWith(player.UserId) then
                    friendList[player.Name] = true
                end
            end)
        end
    end
    lastFriendUpdate = currentTime
end

local function getFriendTycoons()
    local tycoonsFolder = workspace:FindFirstChild("Tycoons")
    if not tycoonsFolder then return {} end

    local friendTycoons = {}

    for _, tycoon in ipairs(tycoonsFolder:GetChildren()) do
        local playerValue = tycoon:FindFirstChild("Player")
        if playerValue then
            local ownerName = nil
            if playerValue:IsA("ObjectValue") and playerValue.Value then
                ownerName = playerValue.Value.Name
            elseif playerValue:IsA("StringValue") and playerValue.Value ~= "" then
                ownerName = playerValue.Value
            end

            if ownerName and friendList[ownerName] then
                table.insert(friendTycoons, tycoon)
            end
        end
    end

    return friendTycoons
end

local function instantRemoteTrigger(prompt)
    if not AutoFarmFriendsModule.Enabled then return end
    if activeInteractions[prompt] then return end
    if prompt.ActionText == "Cook" or prompt.ObjectText == "Cook" or prompt.Name == "Cook" then return end

    activeInteractions[prompt] = true

    task.spawn(function()
        pcall(function()
            if fireproximityprompt then
                fireproximityprompt(prompt)
            else
                prompt:InputHoldBegin()
                task.wait(prompt.HoldDuration + 0.01)
                prompt:InputHoldEnd()
            end
        end)

        task.wait(0.05)
        activeInteractions[prompt] = nil
    end)
end

function AutoFarmFriendsModule.Start()
    if AutoFarmFriendsModule.Enabled then return end
    AutoFarmFriendsModule.Enabled = true
    updateFriendsList()

    farmThread = task.spawn(function()
        while AutoFarmFriendsModule.Enabled do
            updateFriendsList()

            pcall(function()
                local friendTycoons = getFriendTycoons()
                for _, tycoon in ipairs(friendTycoons) do
                    if not AutoFarmFriendsModule.Enabled then break end
                    local tycoonDescendants = tycoon:GetDescendants()
                    for i = 1, #tycoonDescendants do
                        if not AutoFarmFriendsModule.Enabled then break end
                        local desc = tycoonDescendants[i]
                        if desc:IsA("ProximityPrompt") and desc.Name == "CustomerInteractPrompt" and desc.Enabled then
                            instantRemoteTrigger(desc)
                        end
                    end
                end
            end)

            local tempFolder = workspace:FindFirstChild("Temp")
            if tempFolder then
                pcall(function()
                    local tempDescendants = tempFolder:GetDescendants()
                    for i = 1, #tempDescendants do
                        if not AutoFarmFriendsModule.Enabled then break end
                        local desc = tempDescendants[i]
                        if desc:IsA("ProximityPrompt") and desc.Enabled then
                            instantRemoteTrigger(desc)
                        end
                    end
                end)
            end

            jitter(0.1)
        end
    end)
    print("[Auto Farm Friends] Ativado com Sucesso!")
end

function AutoFarmFriendsModule.Stop()
    if not AutoFarmFriendsModule.Enabled then return end
    AutoFarmFriendsModule.Enabled = false
    table.clear(activeInteractions)

    local thread = farmThread
    farmThread = nil
    if thread then
        pcall(function()
            if type(task) == "table" and type(task.cancel) == "function" then
                task.cancel(thread)
            elseif type(coroutine.close) == "function" then
                coroutine.close(thread)
            end
        end)
    end

    print("[Auto Farm Friends] Desativado!")
end

function AutoFarmFriendsModule.Toggle(state)
    if state then
        AutoFarmFriendsModule.Start()
    else
        AutoFarmFriendsModule.Stop()
    end
end

AutoFarmFriendsModule.Set = AutoFarmFriendsModule.Toggle

return AutoFarmFriendsModule
]],
    ["src/games/features/restauranttycoon3/autofarm.lua"] = [[
local cl_game = game
local cl_workspace = workspace
local cl_players = cl_game:GetService("Players")
local cl_localplayer = cl_players.LocalPlayer

local cl_findfirstchild = cl_game.FindFirstChild
local cl_getdescendants = cl_game.GetDescendants
local cl_getchildren = cl_game.GetChildren
local cl_isa = cl_game.IsA

local cl_task = task
local cl_spawn = cl_task.spawn
local cl_wait = cl_task.wait
local cl_cancel = cl_task.cancel

local cl_pcall = pcall
local cl_clear = table.clear
local cl_vector3 = Vector3.new

local cl_fireprompt = fireproximityprompt or nil
local cl_fireclick = fireclickdetector or nil
local cl_vu = cl_game:GetService("VirtualUser")

local AutoFarmModule = {}
AutoFarmModule.Enabled = false

local activeInteractions = {}
local farmThread = nil

local function getMyTycoon()
    local tycoonsFolder = cl_findfirstchild(cl_workspace, "Tycoons")
    if not tycoonsFolder then return nil end

    local children = cl_getchildren(tycoonsFolder)
    for i = 1, #children do
        local tycoon = children[i]
        local playerValue = cl_findfirstchild(tycoon, "Player")
        if playerValue then
            if cl_isa(playerValue, "ObjectValue") and playerValue.Value == cl_localplayer then
                return tycoon
            end

            if cl_isa(playerValue, "StringValue") and tostring(playerValue.Value) == cl_localplayer.Name then
                return tycoon
            end
        end
    end

    return nil
end

local function interactWithModel(model)
    if not AutoFarmModule.Enabled or activeInteractions[model] then return end
    activeInteractions[model] = true

    cl_spawn(function()
        cl_pcall(function()
            local character = cl_localplayer.Character
            local rootPart = character and cl_findfirstchild(character, "HumanoidRootPart")
            local targetPart = model.PrimaryPart or cl_findfirstchild(model, "Part", true) or cl_findfirstchild(model, "Base", true) or cl_findfirstchild(model, "MeshPart", true)

            if rootPart and targetPart and cl_isa(targetPart, "BasePart") then
                local originalCFrame = rootPart.CFrame
                rootPart.CFrame = targetPart.CFrame * CFrame.new(cl_vector3(0, 1.5, 0))
                cl_wait(0.012)

                local detector = cl_findfirstchild(model, "ClickDetector", true) or cl_findfirstchild(targetPart, "ClickDetector")
                if detector and cl_fireclick then
                    cl_fireclick(detector)
                else
                    cl_vu:ClickButton1(cl_vector3(0, 0, 0), cl_workspace.CurrentCamera.CFrame)
                end

                cl_wait(0.01)
                rootPart.CFrame = originalCFrame
            end
        end)
        cl_wait(0.04)
        activeInteractions[model] = nil
    end)
end

local function triggerPrompt(prompt)
    if not AutoFarmModule.Enabled or activeInteractions[prompt] then return end

    local name = prompt.Name
    local action = prompt.ActionText
    local object = prompt.ObjectText

    if action == "Cook" or object == "Cook" or name == "Cook" then return end

    activeInteractions[prompt] = true

    cl_spawn(function()
        cl_pcall(function()
            local character = cl_localplayer.Character
            local rootPart = character and cl_findfirstchild(character, "HumanoidRootPart")
            local parentPart = prompt.Parent

            local originalCFrame
            local targetPart = nil

            if parentPart then
                if cl_isa(parentPart, "BasePart") then
                    targetPart = parentPart
                elseif cl_isa(parentPart, "Model") then
                    targetPart = cl_findfirstchild(parentPart, "HumanoidRootPart") or parentPart.PrimaryPart or cl_findfirstchild(parentPart, "Part", true)
                end
            end

            if rootPart and targetPart then
                originalCFrame = rootPart.CFrame
                rootPart.CFrame = targetPart.CFrame * CFrame.new(cl_vector3(0, 1.5, 0))
                cl_wait(0.012)
            end

            if cl_fireprompt then
                cl_fireprompt(prompt)
            else
                prompt:InputHoldBegin()
                cl_wait(prompt.HoldDuration + 0.01)
                prompt:InputHoldEnd()
            end

            if rootPart and originalCFrame then
                rootPart.CFrame = originalCFrame
            end
        end)

        cl_wait(0.04)
        activeInteractions[prompt] = nil
    end)
end

function AutoFarmModule.Start()
    if AutoFarmModule.Enabled then return end
    AutoFarmModule.Enabled = true

    farmThread = cl_spawn(function()
        local myTycoon

        while AutoFarmModule.Enabled do
            if not myTycoon or not myTycoon.Parent then
                myTycoon = getMyTycoon()
            end

            if myTycoon then
                cl_pcall(function()
                    local items = cl_findfirstchild(myTycoon, "Items")
                    local surface = items and cl_findfirstchild(items, "Surface")

                    if surface then
                        local surfaceDescendants = cl_getdescendants(surface)
                        for i = 1, #surfaceDescendants do
                            local desc = surfaceDescendants[i]
                            if not AutoFarmModule.Enabled then break end

                            if cl_isa(desc, "Model") and (desc.Name == "Bill" or desc.Name == "Trash") then
                                interactWithModel(desc)
                            end
                        end
                    end

                    local tycoonDescendants = cl_getdescendants(myTycoon)
                    for i = 1, #tycoonDescendants do
                        local desc = tycoonDescendants[i]
                        if not AutoFarmModule.Enabled then break end

                        if cl_isa(desc, "ProximityPrompt") and desc.Name == "CustomerInteractPrompt" and desc.Enabled then
                            triggerPrompt(desc)
                        end
                    end
                end)
            end

            cl_wait(0.08)
        end
    end)
end

function AutoFarmModule.Stop()
    if not AutoFarmModule.Enabled then return end
    AutoFarmModule.Enabled = false
    cl_clear(activeInteractions)

    if farmThread then
        cl_pcall(function()
            cl_cancel(farmThread)
        end)
        farmThread = nil
    end
end

function AutoFarmModule.Toggle(state)
    if state then
        AutoFarmModule.Start()
    else
        AutoFarmModule.Stop()
    end
end

AutoFarmModule.Set = AutoFarmModule.Toggle

return AutoFarmModule

]],
    ["src/games/features/restauranttycoon3/drops.lua"] = [[
local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")
local localPlayer = Players.LocalPlayer

local AutoDropModule = {}
AutoDropModule.Enabled = false

-- Humanised timing: vary the poll interval so the scan loop is not perfectly periodic.
local function jitter(base, spread)
    spread = spread or 0.15
    return task.wait(base * (1 + (math.random() * 2 - 1) * spread))
end

local dropThread = nil
local dropConnection = nil
local boundFolder = nil
local generation = 0
local activeDrops = {}

local function processDrop(drop)
    if not AutoDropModule.Enabled or activeDrops[drop] then return end

    local character = localPlayer.Character
    local hrp = character and character:FindFirstChild("HumanoidRootPart")
    if not hrp then return end

    local token = generation
    activeDrops[drop] = token
    task.spawn(function()
        if not AutoDropModule.Enabled or token ~= generation or not drop.Parent or localPlayer.Character ~= hrp.Parent then
            if activeDrops[drop] == token then activeDrops[drop] = nil end
            return
        end
        pcall(function()
            local touchInterest = drop:FindFirstChildOfClass("TouchInterest") or drop:FindFirstChild("TouchInterest")
            if touchInterest and firetouchinterest then
                firetouchinterest(hrp, drop, 0)
                task.wait(0.01)
                firetouchinterest(hrp, drop, 1)
            elseif drop:IsA("Model") then
                drop:PivotTo(hrp.CFrame)
            elseif drop:IsA("BasePart") then
                drop.CFrame = hrp.CFrame
            end
        end)

        task.wait(0.1)
        if activeDrops[drop] == token then activeDrops[drop] = nil end
    end)
end

function AutoDropModule.Start()
    if AutoDropModule.Enabled then return end
    AutoDropModule.Enabled = true
    generation += 1

    dropThread = task.spawn(function()
        while AutoDropModule.Enabled do
            local dropFolder = Workspace:FindFirstChild("DropFolder")

            if dropFolder ~= boundFolder then
                if dropConnection then dropConnection:Disconnect(); dropConnection = nil end
                boundFolder = dropFolder
            end
            if dropFolder then
                if not dropConnection then
                    dropConnection = dropFolder.ChildAdded:Connect(function(child)
                        if AutoDropModule.Enabled then
                            processDrop(child)
                        end
                    end)
                end

                pcall(function()
                    for _, drop in ipairs(dropFolder:GetChildren()) do
                        if not AutoDropModule.Enabled then break end
                        processDrop(drop)
                    end
                end)
            end

            jitter(0.15)
        end
    end)
end

function AutoDropModule.Stop()
    if not AutoDropModule.Enabled then return end
    AutoDropModule.Enabled = false
    generation += 1
    boundFolder = nil
    table.clear(activeDrops)

    if dropConnection then
        pcall(function()
            dropConnection:Disconnect()
        end)
        dropConnection = nil
    end

    if dropThread then
        pcall(function()
            task.cancel(dropThread)
        end)
        dropThread = nil
    end
end

function AutoDropModule.Toggle(state)
    if state then
        AutoDropModule.Start()
    else
        AutoDropModule.Stop()
    end
end

AutoDropModule.Set = AutoDropModule.Toggle

return AutoDropModule


]],
    ["src/games/features/restauranttycoon3/instant-cook.lua"] = [[
local cl_game = game
local cl_workspace = workspace
local cl_players = cl_game:GetService("Players")
local cl_localplayer = cl_players.LocalPlayer

local cl_findfirstchild = cl_game.FindFirstChild
local cl_getdescendants = cl_game.GetDescendants
local cl_getchildren = cl_game.GetChildren
local cl_isa = cl_game.IsA

local cl_task = task
local cl_spawn = cl_task.spawn
local cl_wait = cl_task.wait
local cl_cancel = cl_task.cancel

local cl_pcall = pcall
local cl_clear = table.clear
local cl_vector3 = Vector3.new

local cl_fireprompt = fireproximityprompt or nil

local cl_replicatedstorage = cl_game:GetService("ReplicatedStorage")
local cl_runservice = cl_game:GetService("RunService")

local eventsFolder = cl_findfirstchild(cl_replicatedstorage, "Events")
local cookFolder = eventsFolder and cl_findfirstchild(eventsFolder, "Cook")
local cookInputRemote = cookFolder and cl_findfirstchild(cookFolder, "CookInputRequested")
local cookUpdatedEvent = cookFolder and cl_findfirstchild(cookFolder, "CookUpdated")

local CookModule = {
    Enabled = false,
    FixedPosition = nil,
    IsCooking = false
}

local connections = {}
local loopThreads = {}

local function getMyTycoon()
    local tycoonsFolder = cl_findfirstchild(cl_workspace, "Tycoons")
    if not tycoonsFolder then return nil end

    local children = cl_getchildren(tycoonsFolder)
    for i = 1, #children do
        local tycoon = children[i]
        local playerValue = cl_findfirstchild(tycoon, "Player")
        if playerValue then
            if cl_isa(playerValue, "ObjectValue") and playerValue.Value == cl_localplayer then
                return tycoon
            end

            if cl_isa(playerValue, "StringValue") and tostring(playerValue.Value) == cl_localplayer.Name then
                return tycoon
            end
        end
    end

    return nil
end

local function belongsToMyTycoon(instance, tycoon)
    if not instance or not tycoon then return false end
    return instance == tycoon or instance:IsDescendantOf(tycoon)
end

local function unanchorCharacter()
    local character = cl_localplayer.Character
    if not character then return end

    local descendants = cl_getdescendants(character)
    for i = 1, #descendants do
        local part = descendants[i]
        if cl_isa(part, "BasePart") and part.Anchored then
            part.Anchored = false
        end
    end
end

local function instantProcess(equipment, stationType, myTycoon)
    if not CookModule.Enabled or not equipment or not stationType or not cookInputRemote then return end
    if not belongsToMyTycoon(equipment, myTycoon) then return end

    CookModule.IsCooking = true
    unanchorCharacter()

    local character = cl_localplayer.Character
    local hrp = character and cl_findfirstchild(character, "HumanoidRootPart")
    if hrp then
        CookModule.FixedPosition = hrp.CFrame
    end

    cl_spawn(function()
        cl_pcall(function()
            cookInputRemote:FireServer("Interact", equipment, stationType)
            cl_wait(0.02)
            cookInputRemote:FireServer("CompleteTask", equipment, stationType, false)
        end)
        cl_wait(0.03)
        unanchorCharacter()
        CookModule.IsCooking = false
        CookModule.FixedPosition = nil
    end)
end

function CookModule.Start()
    if CookModule.Enabled then return end
    CookModule.Enabled = true

    connections[#connections + 1] = cl_runservice.Heartbeat:Connect(function()
        if not CookModule.Enabled then return end

        unanchorCharacter()

        if not CookModule.IsCooking or not CookModule.FixedPosition then return end

        local character = cl_localplayer.Character
        if not character then return end

        local root = cl_findfirstchild(character, "HumanoidRootPart")
        if root then
            if (root.Position - CookModule.FixedPosition.Position).Magnitude > 0.05 then
                root.CFrame = CookModule.FixedPosition
            end
            root.AssemblyLinearVelocity = cl_vector3(0, 0, 0)
            root.AssemblyAngularVelocity = cl_vector3(0, 0, 0)
        end

        local humanoid = cl_findfirstchild(character, "Humanoid")
        if humanoid and humanoid.PlatformStand then
            humanoid.PlatformStand = false
        end
    end)

    local myTycoon = getMyTycoon()

    if cookUpdatedEvent then
        connections[#connections + 1] = cookUpdatedEvent.OnClientEvent:Connect(function(actionType, p1, p2, p3, p4)
            if not CookModule.Enabled then return end

            local currentTycoon = myTycoon
            if not currentTycoon or not currentTycoon.Parent then
                currentTycoon = getMyTycoon()
                myTycoon = currentTycoon
            end

            if actionType == "DirectToEquipment" and typeof(p1) == "Instance" then
                instantProcess(p1, p2, currentTycoon)
            elseif actionType == "UpdateInteraction" and typeof(p2) == "Instance" and p4 == true then
                instantProcess(p2, p3, currentTycoon)
            end
        end)
    end

    loopThreads[#loopThreads + 1] = cl_spawn(function()
        while CookModule.Enabled do
            if not myTycoon or not myTycoon.Parent then
                myTycoon = getMyTycoon()
            end

            if myTycoon and not CookModule.IsCooking then
                cl_pcall(function()
                    local descendants = cl_getdescendants(myTycoon)
                    for i = 1, #descendants do
                        if not CookModule.Enabled or CookModule.IsCooking then break end

                        local desc = descendants[i]
                        if cl_isa(desc, "ProximityPrompt") and desc.Enabled and (desc.ActionText == "Cook" or desc.ObjectText == "Cook" or desc.Name == "Cook") then
                            unanchorCharacter()

                            local character = cl_localplayer.Character
                            local hrp = character and cl_findfirstchild(character, "HumanoidRootPart")
                            if hrp then
                                CookModule.FixedPosition = hrp.CFrame
                            end

                            CookModule.IsCooking = true

                            cl_pcall(function()
                                if cl_fireprompt then
                                    cl_fireprompt(desc)
                                else
                                    desc:InputHoldBegin()
                                    cl_wait(desc.HoldDuration + 0.005)
                                    desc:InputHoldEnd()
                                end
                            end)

                            cl_wait(0.05)
                            unanchorCharacter()
                            CookModule.IsCooking = false
                            CookModule.FixedPosition = nil
                        end
                    end
                end)
            end

            cl_wait(0.1)
        end
    end)
end

function CookModule.Stop()
    if not CookModule.Enabled then return end
    CookModule.Enabled = false
    CookModule.IsCooking = false

    for i = 1, #connections do
        local connection = connections[i]
        if connection then
            connection:Disconnect()
        end
    end

    for i = 1, #loopThreads do
        local thread = loopThreads[i]
        if thread then
            cl_cancel(thread)
        end
    end

    cl_clear(connections)
    cl_clear(loopThreads)
    CookModule.FixedPosition = nil
    unanchorCharacter()
end

function CookModule.Toggle(state)
    if state then
        CookModule.Start()
    else
        CookModule.Stop()
    end
end

CookModule.Set = CookModule.Toggle

return CookModule

